CREATE OR REPLACE FUNCTION lms.log_tenant_billing_mode()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'lms', 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.billing_mode <> 'paid' THEN
      INSERT INTO tenant_billing_mode_log (tenant_id, old_mode, new_mode, fee_percent_override, comped_until, reason)
      VALUES (NEW.id, NULL, NEW.billing_mode, NEW.fee_percent_override, NEW.comped_until, NEW.comped_reason);
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.billing_mode IS DISTINCT FROM OLD.billing_mode
     OR (NEW.billing_mode = 'comped'
         AND (NEW.fee_percent_override IS DISTINCT FROM OLD.fee_percent_override
              OR NEW.comped_until IS DISTINCT FROM OLD.comped_until)) THEN
    INSERT INTO tenant_billing_mode_log (tenant_id, old_mode, new_mode, fee_percent_override, comped_until, reason)
    VALUES (NEW.id, OLD.billing_mode, NEW.billing_mode, NEW.fee_percent_override, NEW.comped_until, NEW.comped_reason);
  END IF;
  RETURN NEW;
END;
$function$;

REVOKE EXECUTE ON FUNCTION lms.log_tenant_billing_mode() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS trg_log_tenant_billing_mode_update ON lms.tenants;
CREATE TRIGGER trg_log_tenant_billing_mode_update
  AFTER UPDATE OF billing_mode, fee_percent_override, comped_until ON lms.tenants
  FOR EACH ROW EXECUTE FUNCTION lms.log_tenant_billing_mode();

DROP TRIGGER IF EXISTS trg_log_tenant_billing_mode_insert ON lms.tenants;
CREATE TRIGGER trg_log_tenant_billing_mode_insert
  AFTER INSERT ON lms.tenants
  FOR EACH ROW WHEN (NEW.billing_mode <> 'paid')
  EXECUTE FUNCTION lms.log_tenant_billing_mode();

-- ─── 3. Data migration ──────────────────────────────────────────────────────
-- Runs after the trigger so each change lands in the log. Order matters: the old
-- columns are read here and dropped in steps 5 / 9.

UPDATE lms.tenants
SET billing_mode = 'internal', comped_reason = 'platform tenant', comped_at = now()
WHERE id = '00000000-0000-0000-0000-000000000001' AND billing_mode = 'paid';

-- plan_override schools (forced plan, no Stripe change) -> comped, keeping today's fee.
UPDATE lms.tenants t
SET billing_mode = 'comped',
    comped_reason = 'migrated from plan_override',
    comped_by = ps.plan_override_by,
    comped_at = ps.plan_override_at,
    fee_percent_override = LEAST(100, GREATEST(0, COALESCE(
      (SELECT 100 - rs.school_percentage FROM lms.revenue_splits rs WHERE rs.tenant_id = t.id), 20)))
FROM lms.platform_subscriptions ps
WHERE ps.tenant_id = t.id
  AND ps.plan_override_at IS NOT NULL
  AND t.id <> '00000000-0000-0000-0000-000000000001'
  AND t.billing_mode = 'paid';

-- fee-exempt schools not already marked -> comped, keeping today's fee.
UPDATE lms.tenants t
SET billing_mode = 'comped',
    comped_reason = 'migrated from fee exemption',
    comped_by = s.exempt_set_by,
    comped_at = COALESCE(s.exempt_set_at, now()),
    fee_percent_override = LEAST(100, GREATEST(0, COALESCE(
      (SELECT 100 - rs.school_percentage FROM lms.revenue_splits rs WHERE rs.tenant_id = t.id), 20)))
FROM lms.tenant_fee_standing s
WHERE s.tenant_id = t.id
  AND s.enforcement_exempt
  AND t.id <> '00000000-0000-0000-0000-000000000001'
  AND t.billing_mode = 'paid';

-- ─── 4. effective_school_percentage + consumers ─────────────────────────────

-- SQL twin of effectiveSchoolPercentage() in lib/billing/effective-fee.ts.
CREATE OR REPLACE FUNCTION lms.effective_school_percentage(_tenant_id uuid)
RETURNS numeric
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'lms', 'public'
AS $function$
  SELECT CASE t.billing_mode
    WHEN 'internal' THEN 100::numeric
    WHEN 'comped' THEN 100 - LEAST(100, GREATEST(0, COALESCE(t.fee_percent_override, 0)))
    ELSE COALESCE(
      (SELECT rs.school_percentage FROM revenue_splits rs WHERE rs.tenant_id = _tenant_id),
      80
    )
  END
  FROM (SELECT 1) d
  LEFT JOIN tenants t ON t.id = _tenant_id;
$function$;

COMMENT ON FUNCTION lms.effective_school_percentage(uuid) IS
  'Issue #982: the school''s share of a student sale. internal -> 100; comped -> 100 - fee_percent_override (NULL = 0); paid or unknown tenant -> revenue_splits.school_percentage else 80. TS twin: lib/billing/effective-fee.ts.';

REVOKE EXECUTE ON FUNCTION lms.effective_school_percentage(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.effective_school_percentage(uuid) TO service_role;

-- Body from 20260725110000_transaction_split_snapshot_backstop.sql; only the value source changed.
CREATE OR REPLACE FUNCTION lms.set_transaction_split_snapshot()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'lms', 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Already snapshotted: frozen. Restoring OLD rather than comparing-and-
    -- raising means a tampering UPDATE is neutralised instead of failing the
    -- whole webhook that happened to carry it.
    IF OLD.school_percentage_snapshot IS NOT NULL THEN
      NEW.school_percentage_snapshot := OLD.school_percentage_snapshot;
      RETURN NEW;
    END IF;

    -- Legacy NULL row. Fill it only if a provider is activating it right now;
    -- otherwise keep the documented NULL fallback and discard whatever the
    -- caller tried to put there.
    IF NEW.payment_provider IS NOT DISTINCT FROM OLD.payment_provider THEN
      NEW.school_percentage_snapshot := NULL;
      RETURN NEW;
    END IF;
  END IF;

  -- INSERT, or the legacy-row activation case above. Either way the value is
  -- computed here; anything the caller supplied is ignored.
  IF NEW.tenant_id IS NULL THEN
    NEW.school_percentage_snapshot := NULL;
    RETURN NEW;
  END IF;

  -- #982: billing_mode aware (internal 100, comped 100 - override, paid the
  -- revenue_splits row else 80). Was: COALESCE(revenue_splits.school_percentage, 80).
  NEW.school_percentage_snapshot := lms.effective_school_percentage(NEW.tenant_id);

  RETURN NEW;
END;
$function$;

COMMENT ON FUNCTION lms.set_transaction_split_snapshot() IS
  'Backstop for #496 (issue #512): owns transactions.school_percentage_snapshot. Computes it via effective_school_percentage() (#982: billing_mode aware) on INSERT and freezes it on UPDATE, so neither an insert path that forgets nor a client that tampers can affect the payout computation. Legacy NULL rows are filled only when a provider activates them (payment_provider changing), never on an incidental update.';

-- Body from 20261009100000_platform_fee_ledger_929.sql; only the fallback pct source changed
-- (a transaction snapshot still wins).
CREATE OR REPLACE FUNCTION lms.platform_fee_ledger(_tenant_id uuid, _accrued_before timestamptz DEFAULT NULL)
RETURNS TABLE (currency text, accrued numeric, paid numeric, sales integer)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'lms', 'public'
AS $function$
  WITH cfg AS (
    SELECT COALESCE(
      (SELECT hyperinflation_currencies FROM platform_fee_config WHERE id),
      '{VES}'::text[]
    ) AS hyper
  ),
  split AS (
    SELECT COALESCE(
      lms.effective_school_percentage(_tenant_id),
      80
    ) AS pct
  ),
  src_rows AS (
    SELECT
      upper(COALESCE(t.currency::text, 'usd')) AS src,
      t.amount,
      GREATEST(t.amount - COALESCE(t.refunded_amount, 0), 0) AS kept,
      t.usd_amount,
      COALESCE(t.school_percentage_snapshot, split.pct) AS pct
    FROM transactions t, split
    WHERE t.tenant_id = _tenant_id
      AND t.payment_provider IN ('manual', 'binance_personal')
      AND t.status = 'successful'
      AND t.amount > 0
      AND (_accrued_before IS NULL OR t.transaction_date < _accrued_before)
  ),
  based AS (
    SELECT
      CASE WHEN r.src = ANY (cfg.hyper) AND r.usd_amount IS NOT NULL THEN 'USD' ELSE r.src END AS bucket,
      CASE WHEN r.src = ANY (cfg.hyper) AND r.usd_amount IS NOT NULL
           THEN round(r.usd_amount * r.kept / r.amount, 2)
           ELSE r.kept END AS base,
      r.pct
    FROM src_rows r, cfg
    WHERE r.kept > 0.005
  ),
  fees AS (
    SELECT bucket, sum(base - round(base * pct / 100, 2)) AS accrued, count(*)::integer AS sales
    FROM based
    GROUP BY bucket
  ),
  pays AS (
    SELECT p.currency AS bucket, sum(p.amount) AS paid
    FROM platform_fee_payments p
    WHERE p.tenant_id = _tenant_id
      AND p.status = 'succeeded'
    GROUP BY p.currency
  )
  SELECT
    COALESCE(f.bucket, p.bucket) AS currency,
    COALESCE(f.accrued, 0) AS accrued,
    COALESCE(p.paid, 0) AS paid,
    COALESCE(f.sales, 0) AS sales
  FROM fees f
  FULL JOIN pays p ON p.bucket = f.bucket
  ORDER BY 1;
$function$;

COMMENT ON FUNCTION lms.platform_fee_ledger(uuid, timestamptz) IS
  'Issue #929: platform fee balance per ledger currency for one tenant (SQL mirror of lib/payments/platform-fee-owed.ts computeFeeBalances). Fallback pct is effective_school_percentage (#982). Service role only.';

-- Body from 20260727130000_partial_refunds_and_payout_idempotency.sql; only the fee source
-- changed (a transaction snapshot still wins).
create or replace function lms.get_platform_revenue(
  _start timestamptz default null,
  _end   timestamptz default null
)
returns jsonb
language plpgsql
security definer
set search_path = lms, public
as $$
declare
  result jsonb;
  v_mrr  numeric;
  -- Mirror of ProviderCapabilities.bearsPlatformFee (lib/payments/types.ts).
  v_fee_bearing text[] := array['stripe', 'paypal', 'lemonsqueezy', 'binance', 'solana', 'solana_subs'];
begin
  -- SaaS MRR (schools paying the platform), normalized to monthly dollars.
  select coalesce(sum(
    case when ps.interval = 'yearly' then pp.price_yearly / 12.0
         else pp.price_monthly end
  ), 0)::numeric
  into v_mrr
  from platform_subscriptions ps
  join platform_plans pp on pp.plan_id = ps.plan_id
  where ps.status = 'active';

  with tx as (
    select
      t.tenant_id,
      greatest(t.amount - coalesce(t.refunded_amount, 0), 0) as amount,
      t.transaction_date,
      coalesce(
        t.payment_provider,
        case when t.stripe_payment_intent_id is not null then 'stripe' else 'manual' end
      ) as provider,
      -- Platform share = 100 - the school's share, snapshotted per transaction.
      100 - coalesce(t.school_percentage_snapshot, lms.effective_school_percentage(t.tenant_id)) as platform_percentage
    from transactions t
    where t.status = 'successful'
      and (_start is null or t.transaction_date >= _start)
      and (_end   is null or t.transaction_date <= _end)
  ),
  tx_fee as (
    select
      tenant_id,
      amount,
      transaction_date,
      provider,
      case when provider = any(v_fee_bearing)
           then round(amount * platform_percentage / 100.0, 2)
           else 0 end as platform_fee
    from tx
  )
  select jsonb_build_object(
    'gmv',               (select coalesce(sum(amount), 0)       from tx_fee),
    'platform_fees',     (select coalesce(sum(platform_fee), 0) from tx_fee),
    'transaction_count', (select count(*)                       from tx_fee),
    'saas_mrr',          round(v_mrr, 2),
    'by_provider', (
      select coalesce(jsonb_agg(row order by row->>'fees' desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'provider', provider,
          'gmv',   round(sum(amount), 2),
          'fees',  round(sum(platform_fee), 2),
          'count', count(*)
        ) as row
        from tx_fee
        group by provider
      ) p
    ),
    'by_tenant', (
      select coalesce(jsonb_agg(row order by (row->>'fees')::numeric desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'tenant_id', tf.tenant_id,
          'name',      coalesce(tn.name, 'Unknown'),
          'plan',      coalesce(tn.plan, 'free'),
          'gmv',   round(sum(tf.amount), 2),
          'fees',  round(sum(tf.platform_fee), 2),
          'count', count(*)
        ) as row
        from tx_fee tf
        left join tenants tn on tn.id = tf.tenant_id
        group by tf.tenant_id, tn.name, tn.plan
      ) t
    ),
    'monthly', (
      select coalesce(jsonb_agg(row order by row->>'month'), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'month', to_char(date_trunc('month', transaction_date), 'YYYY-MM'),
          'gmv',  round(sum(amount), 2),
          'fees', round(sum(platform_fee), 2)
        ) as row
        from tx_fee
        group by date_trunc('month', transaction_date)
        order by date_trunc('month', transaction_date)
      ) m
    )
  )
  into result;

  return result;
end;
$$;

comment on function lms.get_platform_revenue(timestamptz, timestamptz) is
  'Platform super-admin revenue/fees aggregated across all tenants: GMV net of refunds, computed platform fees (per-transaction snapshotted split, else effective_school_percentage; fee-bearing providers only), SaaS MRR, and by-provider/by-tenant/monthly breakdowns. Called by /platform/revenue.';

-- ─── 5. Fee blocking: only paid schools ─────────────────────────────────────
-- Replaces the NOT enforcement_exempt clause (20261009130000). comped = notify only,
-- internal = never. Grants unchanged (service_role).

CREATE OR REPLACE FUNCTION lms.is_tenant_sales_blocked(_tenant_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'lms', 'public'
AS $function$
  SELECT COALESCE(
    (SELECT c.enforcement_mode = 'enforce' FROM platform_fee_config c WHERE c.id),
    false
  )
  AND EXISTS (
    SELECT 1 FROM tenant_fee_standing s
    WHERE s.tenant_id = _tenant_id
      AND s.blocked_at IS NOT NULL
  )
  AND (SELECT t.billing_mode FROM tenants t WHERE t.id = _tenant_id) = 'paid';
$function$;

COMMENT ON FUNCTION lms.is_tenant_sales_blocked(uuid) IS
  'Issue #929/#982: true only when platform_fee_config.enforcement_mode = enforce AND tenant_fee_standing.blocked_at is set AND tenants.billing_mode = paid (comped = notify only, internal never). Gates NEW sales only; never course access (D5).';

DROP FUNCTION IF EXISTS lms.set_tenant_fee_exemption(uuid, boolean, uuid, text);

ALTER TABLE lms.tenant_fee_standing DROP CONSTRAINT IF EXISTS tenant_fee_standing_exempt_not_blocked;
ALTER TABLE lms.tenant_fee_standing
  DROP COLUMN IF EXISTS enforcement_exempt,
  DROP COLUMN IF EXISTS exempt_reason,
  DROP COLUMN IF EXISTS exempt_set_by,
  DROP COLUMN IF EXISTS exempt_set_at;

-- ─── 6. Plan limits / features ──────────────────────────────────────────────
-- Bodies from 20260901120000_plan_limit_db_triggers.sql and
-- 20261003120000_get_plan_features_ignores_is_active_898.sql.
--   internal            -> unlimited (-1), never hits plan-limit triggers.
--   plan row missing    -> comped uses the `enterprise` row; paid fails closed (0 / '{}').
--   tenant missing      -> NULL (as before).

CREATE OR REPLACE FUNCTION lms.tenant_plan_limit(_tenant_id uuid, _key text)
RETURNS integer
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = lms, public
AS $$
  SELECT CASE
           WHEN t.billing_mode = 'internal' THEN -1
           WHEN pp.plan_id IS NULL THEN 0
           WHEN jsonb_typeof(pp.limits -> _key) = 'number'
             THEN (pp.limits ->> _key)::numeric::integer
           ELSE -1
         END
  FROM lms.tenants t
  LEFT JOIN LATERAL (
    SELECT p.*
    FROM lms.platform_plans p
    WHERE p.slug = COALESCE(t.plan, 'free')
       OR (t.billing_mode = 'comped' AND p.slug = 'enterprise')
    ORDER BY (p.slug = COALESCE(t.plan, 'free')) DESC
    LIMIT 1
  ) pp ON true
  WHERE t.id = _tenant_id;
$$;

COMMENT ON FUNCTION lms.tenant_plan_limit(uuid, text) IS
  'Plan limit for a tenant resolved through tenants.plan → platform_plans.limits. -1 = unlimited (always for internal); a missing plan row resolves to enterprise for comped and to 0 (fail closed) for paid; NULL when the tenant does not exist. Issues #658, #982.';

REVOKE ALL ON FUNCTION lms.tenant_plan_limit(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION lms.tenant_plan_limit(uuid, text) TO service_role;

CREATE OR REPLACE FUNCTION lms.get_plan_features(_tenant_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = lms, public
AS $$
DECLARE
  _plan_slug varchar;
  _mode text;
  _result jsonb;
BEGIN
  SELECT plan, billing_mode INTO _plan_slug, _mode FROM lms.tenants WHERE id = _tenant_id;
  _plan_slug := COALESCE(_plan_slug, 'free');

  -- No is_active filter: a retired plan still governs its subscribers.
  SELECT jsonb_build_object(
    'plan', pp.slug,
    'plan_name', pp.name,
    'features', pp.features,
    'limits', pp.limits,
    'transaction_fee_percent', pp.transaction_fee_percent
  ) INTO _result
  FROM lms.platform_plans pp
  WHERE pp.slug = _plan_slug;

  -- #982: a slug with no row falls back to `enterprise` for comped / internal schools.
  -- A paid school gets '{}' (fail closed); the old free-row fallback is gone.
  IF _result IS NULL AND _mode IN ('comped', 'internal') THEN
    SELECT jsonb_build_object(
      'plan', pp.slug,
      'plan_name', pp.name,
      'features', pp.features,
      'limits', pp.limits,
      'transaction_fee_percent', pp.transaction_fee_percent
    ) INTO _result
    FROM lms.platform_plans pp
    WHERE pp.slug = 'enterprise';
  END IF;

  RETURN COALESCE(_result, '{}'::jsonb);
END;
$$;

COMMENT ON FUNCTION lms.get_plan_features(uuid) IS
  'Plan slug, name, features, limits and fee for a tenant, resolved through tenants.plan → platform_plans with no is_active filter. A slug with no row resolves to the enterprise row for comped / internal schools and to {} for paid ones. #898, #982.';

-- ─── 7. Course access: internal is never suspended ──────────────────────────
-- Body from 20260724130000_access_cutoff_enforcement.sql.

CREATE OR REPLACE FUNCTION lms.has_course_access(_user_id uuid, _course_id integer)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'lms', 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM entitlements e
    JOIN tenants t ON t.id = e.tenant_id
    WHERE e.user_id = _user_id
      AND e.course_id = _course_id
      AND e.status = 'active'
      AND (e.expires_at IS NULL OR e.expires_at > now())
      AND (t.access_cutoff_at IS NULL OR t.access_cutoff_at > now() OR t.billing_mode = 'internal')
  );
$function$;

UPDATE lms.tenants SET access_cutoff_at = NULL
WHERE billing_mode = 'internal' AND access_cutoff_at IS NOT NULL;

-- ─── 8. Real paid subscription converts comped -> paid ──────────────────────
-- Replaces clearing platform_subscriptions.plan_override_*.

-- Bodies from 20260808154118_safe_platform_subscription_switches.sql (promote, downgrade)
-- and 20260808182924_transactional_manual_payment_confirmation.sql (confirm).
CREATE OR REPLACE FUNCTION lms.promote_platform_subscription_switch(
  _switch_id UUID,
  _tenant_id UUID,
  _target_payment_provider TEXT,
  _target_provider_subscription_id TEXT,
  _target_provider_customer_id TEXT,
  _target_plan_id UUID,
  _target_status TEXT,
  _target_interval TEXT,
  _target_period_start TIMESTAMPTZ,
  _target_period_end TIMESTAMPTZ
) RETURNS BOOLEAN
LANGUAGE plpgsql
SET search_path = lms, public
AS $$
DECLARE
  _switch lms.platform_subscription_switches%ROWTYPE;
  _current lms.platform_subscriptions%ROWTYPE;
  _plan_slug TEXT;
  _platform_fee NUMERIC;
  _now TIMESTAMPTZ := now();
BEGIN
  -- Lock the tenant's current entitlement first. Every promotion and exact
  -- terminal downgrade uses this lock order, avoiding a revival/new-checkout
  -- deadlock when both payments arrive together.
  SELECT * INTO _current
  FROM lms.platform_subscriptions
  WHERE tenant_id = _tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN RETURN FALSE; END IF;

  SELECT * INTO _switch
  FROM lms.platform_subscription_switches
  WHERE switch_id = _switch_id AND tenant_id = _tenant_id
  FOR UPDATE;

  IF NOT FOUND
     OR _switch.target_payment_provider <> _target_payment_provider
     OR _switch.target_plan_id <> _target_plan_id
     OR _switch.target_interval <> _target_interval THEN
    RETURN FALSE;
  END IF;

  IF _switch.state IN ('cancellation_pending', 'cancellation_retry', 'cancellation_scheduled', 'completed') THEN
    RETURN _switch.target_provider_subscription_id IS NOT DISTINCT FROM _target_provider_subscription_id;
  END IF;
  IF _switch.state NOT IN ('pending_activation', 'abandoned') THEN
    RETURN FALSE;
  END IF;

  IF _current.subscription_id <> _switch.source_subscription_id
     OR _current.payment_provider <> _switch.source_payment_provider
     OR _current.provider_subscription_id IS DISTINCT FROM _switch.source_provider_subscription_id THEN
    RETURN FALSE;
  END IF;

  -- A provider may settle after its checkout intent expired. The validated
  -- payment wins while the original source is still current; release any newer
  -- unpaid intent so reviving this switch cannot violate the open-switch index.
  IF _switch.state = 'abandoned' THEN
    UPDATE lms.platform_subscription_switches
    SET state = 'abandoned', updated_at = _now
    WHERE tenant_id = _tenant_id
      AND switch_id <> _switch_id
      AND state = 'pending_activation';
  END IF;

  SELECT slug, transaction_fee_percent INTO _plan_slug, _platform_fee
  FROM lms.platform_plans
  WHERE plan_id = _target_plan_id;
  IF NOT FOUND THEN RETURN FALSE; END IF;

  UPDATE lms.platform_subscriptions
  SET plan_id = _target_plan_id,
      payment_provider = _target_payment_provider,
      provider_subscription_id = _target_provider_subscription_id,
      provider_customer_id = _target_provider_customer_id,
      status = _target_status,
      interval = _target_interval,
      current_period_start = _target_period_start,
      current_period_end = _target_period_end,
      cancel_at_period_end = FALSE,
      canceled_at = NULL,
      grace_period_end = NULL,
      renewal_reminder_sent_at = NULL,
      updated_at = _now
  WHERE subscription_id = _current.subscription_id;

  UPDATE lms.tenants
  SET plan = _plan_slug,
      billing_status = _target_status,
      billing_period_end = _target_period_end,
      updated_at = _now
  WHERE id = _tenant_id;

  -- #982: a real paid subscription converts a comped school to paid. internal is untouched.
  UPDATE lms.tenants
  SET billing_mode = 'paid', comped_until = NULL, comped_reason = NULL,
      comped_by = NULL, comped_at = NULL, fee_percent_override = NULL
  WHERE id = _tenant_id AND billing_mode = 'comped';

  INSERT INTO lms.revenue_splits (
    tenant_id, platform_percentage, school_percentage, updated_at
  ) VALUES (
    _tenant_id, _platform_fee, 100 - _platform_fee, _now
  )
  ON CONFLICT (tenant_id) DO UPDATE
  SET platform_percentage = EXCLUDED.platform_percentage,
      school_percentage = EXCLUDED.school_percentage,
      updated_at = EXCLUDED.updated_at;

  UPDATE lms.platform_subscription_switches
  SET target_provider_subscription_id = _target_provider_subscription_id,
      state = 'cancellation_pending',
      activated_at = COALESCE(activated_at, _now),
      next_retry_at = _now,
      last_error = NULL,
      updated_at = _now
  WHERE switch_id = _switch_id;

  RETURN TRUE;
END;
$$;


CREATE OR REPLACE FUNCTION lms.downgrade_platform_subscription_if_current(
  _tenant_id UUID,
  _payment_provider TEXT,
  _provider_subscription_id TEXT
) RETURNS NUMERIC
LANGUAGE plpgsql
SET search_path = lms, public
AS $$
DECLARE
  _current lms.platform_subscriptions%ROWTYPE;
  _platform_fee NUMERIC;
  _now TIMESTAMPTZ := now();
BEGIN
  IF _provider_subscription_id IS NULL THEN RETURN NULL; END IF;

  -- #982: only `paid` schools are auto-downgraded; comped / internal are managed by a super admin.
  IF EXISTS (SELECT 1 FROM lms.tenants WHERE id = _tenant_id AND billing_mode <> 'paid') THEN
    RETURN NULL;
  END IF;

  SELECT * INTO _current
  FROM lms.platform_subscriptions
  WHERE tenant_id = _tenant_id
  FOR UPDATE;

  IF NOT FOUND
     OR _current.payment_provider <> _payment_provider
     OR _current.provider_subscription_id IS DISTINCT FROM _provider_subscription_id THEN
    RETURN NULL;
  END IF;

  SELECT transaction_fee_percent INTO _platform_fee
  FROM lms.platform_plans
  WHERE slug = 'free';
  _platform_fee := COALESCE(_platform_fee, 10);

  UPDATE lms.platform_subscriptions
  SET status = 'canceled', canceled_at = _now, updated_at = _now
  WHERE subscription_id = _current.subscription_id;

  UPDATE lms.tenants
  SET plan = 'free', billing_status = 'free', billing_period_end = NULL, updated_at = _now
  WHERE id = _tenant_id;

  INSERT INTO lms.revenue_splits (
    tenant_id, platform_percentage, school_percentage, updated_at
  ) VALUES (
    _tenant_id, _platform_fee, 100 - _platform_fee, _now
  )
  ON CONFLICT (tenant_id) DO UPDATE
  SET platform_percentage = EXCLUDED.platform_percentage,
      school_percentage = EXCLUDED.school_percentage,
      updated_at = EXCLUDED.updated_at;

  RETURN _platform_fee;
END;
$$;


create or replace function lms.confirm_platform_payment_request(
  _request_id uuid,
  _confirmed_by uuid
)
returns table (
  applied boolean,
  tenant_id uuid,
  switch_id uuid,
  period_start timestamptz,
  period_end timestamptz,
  confirmed_by uuid,
  confirmed_at timestamptz
)
language plpgsql
security invoker
set search_path = ''
as $$
declare
  request_row lms.platform_payment_requests%rowtype;
  subscription_row lms.platform_subscriptions%rowtype;
  plan_slug text;
  platform_fee numeric;
  start_at timestamptz;
  end_at timestamptz;
  promoted boolean;
  confirmed_at_value timestamptz := clock_timestamp();
begin
  if not exists (
    select 1
    from lms.super_admins sa
    where sa.user_id = _confirmed_by
  ) then
    raise exception 'Only super admins can confirm payments'
      using errcode = '42501';
  end if;

  select ppr.* into request_row
  from lms.platform_payment_requests ppr
  where ppr.request_id = _request_id
  for update;

  if not found then
    raise exception 'Payment request not found'
      using errcode = 'P0002';
  end if;

  -- The request row lock makes a concurrent winner visible before this replay
  -- branch runs. A completed request is always a no-op: never restamp the actor
  -- and never derive another paid period.
  if request_row.status = 'confirmed' then
    select ps.* into subscription_row
    from lms.platform_subscriptions ps
    where ps.tenant_id = request_row.tenant_id;

    return query select
      false,
      request_row.tenant_id,
      request_row.switch_id,
      request_row.confirmed_period_start,
      request_row.confirmed_period_end,
      request_row.confirmed_by,
      request_row.confirmed_at;
    return;
  end if;

  if request_row.status = 'rejected' then
    raise exception 'Rejected payments cannot be confirmed'
      using errcode = 'P0001';
  end if;
  if request_row.status = 'expired' then
    raise exception 'Expired payments cannot be confirmed'
      using errcode = 'P0001';
  end if;
  if request_row.status not in ('pending', 'instructions_sent', 'payment_received') then
    raise exception 'Payment request status % cannot be confirmed', request_row.status
      using errcode = 'P0001';
  end if;
  if request_row.expires_at is not null and request_row.expires_at <= confirmed_at_value then
    raise exception 'Expired payments cannot be confirmed'
      using errcode = 'P0001';
  end if;

  select pp.slug, pp.transaction_fee_percent
  into plan_slug, platform_fee
  from lms.platform_plans pp
  where pp.plan_id = request_row.plan_id;

  if not found or plan_slug is null or platform_fee is null then
    raise exception 'Payment request plan is invalid'
      using errcode = 'P0002';
  end if;

  -- This key is shared with apply_self_managed_platform_period. It serializes
  -- different requests for one tenant even when no subscription row exists yet.
  perform pg_advisory_xact_lock(hashtextextended(request_row.tenant_id::text, 625));

  select ps.* into subscription_row
  from lms.platform_subscriptions ps
  where ps.tenant_id = request_row.tenant_id
  for update;

  select p.period_start, p.period_end
  into start_at, end_at
  from lms.calculate_platform_billing_period(
    subscription_row.current_period_end,
    request_row.interval,
    request_row.request_type = 'renewal',
    confirmed_at_value
  ) p;

  if request_row.switch_id is not null then
    select lms.promote_platform_subscription_switch(
      request_row.switch_id,
      request_row.tenant_id,
      coalesce(request_row.payment_provider, 'manual'),
      null,
      null,
      request_row.plan_id,
      'active',
      request_row.interval,
      start_at,
      end_at
    ) into promoted;

    if not coalesce(promoted, false) then
      raise exception 'Subscription switch no longer matches the payment request'
        using errcode = 'P0001';
    end if;

    select ps.* into subscription_row
    from lms.platform_subscriptions ps
    where ps.tenant_id = request_row.tenant_id;
  else
    insert into lms.platform_subscriptions (
      tenant_id,
      plan_id,
      status,
      payment_provider,
      interval,
      current_period_start,
      current_period_end,
      grace_period_end,
      renewal_reminder_sent_at,
      cancel_at_period_end,
      canceled_at,
      updated_at
    ) values (
      request_row.tenant_id,
      request_row.plan_id,
      'active',
      coalesce(request_row.payment_provider, 'manual'),
      request_row.interval,
      start_at,
      end_at,
      null,
      null,
      false,
      null,
      confirmed_at_value
    )
    on conflict on constraint platform_subscriptions_tenant_unique do update set
      plan_id = excluded.plan_id,
      status = excluded.status,
      payment_provider = excluded.payment_provider,
      interval = excluded.interval,
      current_period_start = excluded.current_period_start,
      current_period_end = excluded.current_period_end,
      grace_period_end = null,
      renewal_reminder_sent_at = null,
      cancel_at_period_end = false,
      canceled_at = null,
      updated_at = excluded.updated_at
    returning * into subscription_row;

    update lms.tenants t
    set plan = plan_slug,
        billing_status = 'active',
        billing_period_end = end_at,
        updated_at = confirmed_at_value
    where t.id = request_row.tenant_id;

    if not found then
      raise exception 'Payment request tenant not found'
        using errcode = 'P0002';
    end if;

    -- #982: a real paid period converts a comped school to paid. internal is untouched.
    update lms.tenants t
    set billing_mode = 'paid', comped_until = null, comped_reason = null,
        comped_by = null, comped_at = null, fee_percent_override = null
    where t.id = request_row.tenant_id and t.billing_mode = 'comped';

    insert into lms.revenue_splits (
      tenant_id,
      platform_percentage,
      school_percentage,
      updated_at
    ) values (
      request_row.tenant_id,
      platform_fee,
      100 - platform_fee,
      confirmed_at_value
    )
    on conflict on constraint revenue_splits_tenant_unique do update set
      platform_percentage = excluded.platform_percentage,
      school_percentage = excluded.school_percentage,
      updated_at = excluded.updated_at;
  end if;

  update lms.platform_payment_requests ppr
  set status = 'confirmed',
      confirmed_by = _confirmed_by,
      confirmed_at = confirmed_at_value,
      confirmed_period_start = subscription_row.current_period_start,
      confirmed_period_end = subscription_row.current_period_end,
      updated_at = confirmed_at_value
  where ppr.request_id = request_row.request_id;

  return query select
    true,
    request_row.tenant_id,
    request_row.switch_id,
    subscription_row.current_period_start,
    subscription_row.current_period_end,
    _confirmed_by,
    confirmed_at_value;
end;
$$;


-- Grants as in the source migrations (service role only).
REVOKE ALL ON FUNCTION lms.promote_platform_subscription_switch(
  UUID, UUID, TEXT, TEXT, TEXT, UUID, TEXT, TEXT, TIMESTAMPTZ, TIMESTAMPTZ
) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.promote_platform_subscription_switch(
  UUID, UUID, TEXT, TEXT, TEXT, UUID, TEXT, TEXT, TIMESTAMPTZ, TIMESTAMPTZ
) TO service_role;

REVOKE ALL ON FUNCTION lms.downgrade_platform_subscription_if_current(UUID, TEXT, TEXT)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.downgrade_platform_subscription_if_current(UUID, TEXT, TEXT)
  TO service_role;

REVOKE ALL ON FUNCTION lms.confirm_platform_payment_request(uuid, uuid)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.confirm_platform_payment_request(uuid, uuid)
  TO service_role;

REVOKE ALL ON FUNCTION lms.platform_fee_ledger(uuid, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.platform_fee_ledger(uuid, timestamptz) TO service_role;

REVOKE ALL ON FUNCTION lms.get_platform_revenue(timestamptz, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.get_platform_revenue(timestamptz, timestamptz) TO service_role;

-- ─── 9. Drop plan_override_* (data already moved to billing_mode in step 3) ─

DROP INDEX IF EXISTS lms.idx_platform_subscriptions_plan_override;
ALTER TABLE lms.platform_subscriptions
  DROP COLUMN IF EXISTS plan_override_at,
  DROP COLUMN IF EXISTS plan_override_by;

-- ===========================================================================
-- 20261020140000_tenant_invitations_admin_role.sql
-- ===========================================================================
-- #984: a super admin creating a school on someone's behalf invites the owner as
-- an ADMIN. tenant_invitations.role was limited to student/teacher.
ALTER TABLE lms.tenant_invitations DROP CONSTRAINT IF EXISTS tenant_invitations_role_check;
ALTER TABLE lms.tenant_invitations
  ADD CONSTRAINT tenant_invitations_role_check CHECK (role IN ('student', 'teacher', 'admin'));

-- ===========================================================================
-- 20261020180000_platform_payment_method_catalog.sql
-- ===========================================================================
-- Platform payment methods: platform_bank_accounts learns the same catalog
-- schools already have (#926/#932: Zelle, Binance, PayPal, Zinli, Cash, Pago
-- Movil) next to the original bank transfer.
--
-- Before: every row was a bank account (bank, holder, number all required), so
-- the platform could not publish a Zinli email or a Pago Movil phone to schools
-- paying their platform fee.
--
--   1. `kind` ('bank' default, so every existing row is unchanged) plus `email`
--      and `document` (cedula/RIF for Pago Movil). Binance Pay ID and the Pago
--      Movil phone live in `account_number`, as `identifier` does for schools.
--   2. bank_name / account_holder / account_number become nullable; a CHECK per
--      kind says which ones that kind requires, so a bank row still needs all
--      three and a Zinli row needs only an email.
--   3. One ACTIVE account per (kind, currency) instead of per currency.
--   4. save_platform_bank_account gains _kind/_email/_document (defaulted, so
--      positional callers keep working). Audit rows still hold field names only.

-- ─── 1. Columns ─────────────────────────────────────────────────────────────

ALTER TABLE lms.platform_bank_accounts
  ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'bank',
  ADD COLUMN IF NOT EXISTS email text,
  ADD COLUMN IF NOT EXISTS document text;

ALTER TABLE lms.platform_bank_accounts DROP CONSTRAINT IF EXISTS platform_bank_accounts_kind_valid;
ALTER TABLE lms.platform_bank_accounts ADD CONSTRAINT platform_bank_accounts_kind_valid
  CHECK (kind IN ('bank', 'zelle', 'binance', 'paypal', 'zinli', 'cash', 'pago_movil'));

ALTER TABLE lms.platform_bank_accounts DROP CONSTRAINT IF EXISTS platform_bank_accounts_email_len;
ALTER TABLE lms.platform_bank_accounts ADD CONSTRAINT platform_bank_accounts_email_len
  CHECK (email IS NULL OR (char_length(btrim(email)) BETWEEN 3 AND 254 AND email ~ '^[^\s@]+@[^\s@]+\.[^\s@]+$'));

ALTER TABLE lms.platform_bank_accounts DROP CONSTRAINT IF EXISTS platform_bank_accounts_document_len;
ALTER TABLE lms.platform_bank_accounts ADD CONSTRAINT platform_bank_accounts_document_len
  CHECK (document IS NULL OR char_length(btrim(document)) BETWEEN 1 AND 40);

-- ─── 2. Required fields per kind ────────────────────────────────────────────

ALTER TABLE lms.platform_bank_accounts
  ALTER COLUMN bank_name DROP NOT NULL,
  ALTER COLUMN account_holder DROP NOT NULL,
  ALTER COLUMN account_number DROP NOT NULL;

ALTER TABLE lms.platform_bank_accounts DROP CONSTRAINT IF EXISTS platform_bank_accounts_kind_required;
ALTER TABLE lms.platform_bank_accounts ADD CONSTRAINT platform_bank_accounts_kind_required CHECK (
  CASE kind
    WHEN 'bank' THEN bank_name IS NOT NULL AND account_holder IS NOT NULL AND account_number IS NOT NULL
    WHEN 'zelle' THEN email IS NOT NULL
    WHEN 'binance' THEN account_number IS NOT NULL
    WHEN 'paypal' THEN email IS NOT NULL
    WHEN 'zinli' THEN email IS NOT NULL
    WHEN 'cash' THEN extra_instructions IS NOT NULL
    WHEN 'pago_movil' THEN bank_name IS NOT NULL AND account_number IS NOT NULL AND document IS NOT NULL
    ELSE false
  END
);

-- ─── 3. One active account per kind and currency ────────────────────────────

DROP INDEX IF EXISTS lms.platform_bank_accounts_one_active_per_currency;
CREATE UNIQUE INDEX IF NOT EXISTS platform_bank_accounts_one_active_per_kind_currency
  ON lms.platform_bank_accounts (kind, currency) WHERE is_active;

COMMENT ON TABLE lms.platform_bank_accounts IS
  'Issue #929: platform payment accounts (bank transfer, Zelle, Binance, PayPal, Zinli, cash, Pago Movil) schools pay platform fees into. Managed by super admins (/platform/bank-accounts) through save_/set_platform_bank_account*; one active account per kind and currency. Never readable by schools directly.';

-- ─── 4. Write functions ─────────────────────────────────────────────────────

-- The 13-argument signature is replaced, not overloaded: two overloads would
-- make a positional call ambiguous.
DROP FUNCTION IF EXISTS lms.save_platform_bank_account(uuid, uuid, text, text, text, text, text, text, text, text, text, integer, boolean);

CREATE OR REPLACE FUNCTION lms.save_platform_bank_account(
  _actor uuid,
  _id uuid,
  _currency text,
  _label text,
  _bank_name text DEFAULT NULL,
  _account_holder text DEFAULT NULL,
  _account_number text DEFAULT NULL,
  _account_type text DEFAULT NULL,
  _routing_number text DEFAULT NULL,
  _swift_code text DEFAULT NULL,
  _extra_instructions text DEFAULT NULL,
  _sort_order integer DEFAULT 0,
  _is_active boolean DEFAULT true,
  _kind text DEFAULT 'bank',
  _email text DEFAULT NULL,
  _document text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'lms', 'public'
AS $function$
DECLARE
  _old platform_bank_accounts%ROWTYPE;
  _new platform_bank_accounts%ROWTYPE;
  _changed text[] := ARRAY[]::text[];
  _k text := lower(btrim(coalesce(_kind, 'bank')));
BEGIN
  PERFORM assert_platform_fee_super_admin(_actor);

  IF _id IS NULL THEN
    INSERT INTO platform_bank_accounts (
      kind, currency, label, bank_name, account_holder, account_number, account_type,
      routing_number, swift_code, email, document, extra_instructions, sort_order, is_active,
      created_by, updated_by
    ) VALUES (
      _k, upper(btrim(coalesce(_currency, ''))), btrim(coalesce(_label, '')),
      NULLIF(btrim(_bank_name), ''), NULLIF(btrim(_account_holder), ''), NULLIF(btrim(_account_number), ''),
      NULLIF(btrim(_account_type), ''), NULLIF(btrim(_routing_number), ''),
      NULLIF(upper(regexp_replace(coalesce(_swift_code, ''), '\s', '', 'g')), ''),
      NULLIF(btrim(_email), ''), NULLIF(btrim(_document), ''),
      NULLIF(btrim(_extra_instructions), ''), coalesce(_sort_order, 0), coalesce(_is_active, true),
      _actor, _actor
    )
    RETURNING * INTO _new;

    INSERT INTO platform_fee_audit_log (tenant_id, actor_id, action, currency, details)
    VALUES (NULL, _actor, 'bank_account_created', _new.currency,
            jsonb_build_object('bank_account_id', _new.id, 'label', _new.label, 'kind', _new.kind, 'is_active', _new.is_active));
    RETURN _new.id;
  END IF;

  SELECT * INTO _old FROM platform_bank_accounts WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank account not found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE platform_bank_accounts SET
    kind = _k,
    currency = upper(btrim(coalesce(_currency, ''))),
    label = btrim(coalesce(_label, '')),
    bank_name = NULLIF(btrim(_bank_name), ''),
    account_holder = NULLIF(btrim(_account_holder), ''),
    account_number = NULLIF(btrim(_account_number), ''),
    account_type = NULLIF(btrim(_account_type), ''),
    routing_number = NULLIF(btrim(_routing_number), ''),
    swift_code = NULLIF(upper(regexp_replace(coalesce(_swift_code, ''), '\s', '', 'g')), ''),
    email = NULLIF(btrim(_email), ''),
    document = NULLIF(btrim(_document), ''),
    extra_instructions = NULLIF(btrim(_extra_instructions), ''),
    sort_order = coalesce(_sort_order, 0),
    is_active = coalesce(_is_active, is_active),
    updated_by = _actor,
    updated_at = now()
  WHERE id = _id
  RETURNING * INTO _new;

  -- Field NAMES only: the audit trail never stores account details.
  IF _new.kind IS DISTINCT FROM _old.kind THEN _changed := array_append(_changed, 'kind'); END IF;
  IF _new.currency IS DISTINCT FROM _old.currency THEN _changed := array_append(_changed, 'currency'); END IF;
  IF _new.label IS DISTINCT FROM _old.label THEN _changed := array_append(_changed, 'label'); END IF;
  IF _new.bank_name IS DISTINCT FROM _old.bank_name THEN _changed := array_append(_changed, 'bank_name'); END IF;
  IF _new.account_holder IS DISTINCT FROM _old.account_holder THEN _changed := array_append(_changed, 'account_holder'); END IF;
  IF _new.account_number IS DISTINCT FROM _old.account_number THEN _changed := array_append(_changed, 'account_number'); END IF;
  IF _new.account_type IS DISTINCT FROM _old.account_type THEN _changed := array_append(_changed, 'account_type'); END IF;
  IF _new.routing_number IS DISTINCT FROM _old.routing_number THEN _changed := array_append(_changed, 'routing_number'); END IF;
  IF _new.swift_code IS DISTINCT FROM _old.swift_code THEN _changed := array_append(_changed, 'swift_code'); END IF;
  IF _new.email IS DISTINCT FROM _old.email THEN _changed := array_append(_changed, 'email'); END IF;
  IF _new.document IS DISTINCT FROM _old.document THEN _changed := array_append(_changed, 'document'); END IF;
  IF _new.extra_instructions IS DISTINCT FROM _old.extra_instructions THEN _changed := array_append(_changed, 'extra_instructions'); END IF;
  IF _new.sort_order IS DISTINCT FROM _old.sort_order THEN _changed := array_append(_changed, 'sort_order'); END IF;
  IF _new.is_active IS DISTINCT FROM _old.is_active THEN _changed := array_append(_changed, 'is_active'); END IF;

  INSERT INTO platform_fee_audit_log (tenant_id, actor_id, action, currency, details)
  VALUES (NULL, _actor, 'bank_account_updated', _new.currency,
          jsonb_build_object('bank_account_id', _new.id, 'label', _new.label, 'changed', to_jsonb(_changed)));
  RETURN _new.id;
END;
$function$;

REVOKE EXECUTE ON FUNCTION
  lms.save_platform_bank_account(uuid, uuid, text, text, text, text, text, text, text, text, text, integer, boolean, text, text, text)
FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION
  lms.save_platform_bank_account(uuid, uuid, text, text, text, text, text, text, text, text, text, integer, boolean, text, text, text)
TO service_role;

-- ===========================================================================
-- 20261020200000_tenant_custom_domain_unique.sql
-- ===========================================================================
-- Custom domains: proxy.ts resolves a non-platform host via tenants.domain.
-- Normalise to lower-case and keep each domain pointing at exactly one tenant.
UPDATE tenants SET domain = lower(trim(domain)) WHERE domain IS NOT NULL;
UPDATE tenants SET domain = NULL WHERE domain = '';
CREATE UNIQUE INDEX IF NOT EXISTS idx_tenants_domain_unique ON tenants (lower(domain)) WHERE domain IS NOT NULL;

-- ===========================================================================
-- 20261021100000_platform_metrics_billing_mode.sql
-- ===========================================================================
-- Platform console metrics become billing_mode-aware.
--
-- billing_mode (#982) added paid | comped | internal, but get_platform_stats and
-- get_platform_revenue still summed every active platform_subscriptions row into MRR.
-- comped/internal schools hold an override subscription row (plan comes free), so MRR was
-- inflated (prod at write time: 1975.00 paid vs 2119.83 shown).
--
--   * MRR (mrr_cents / saas_mrr) = paid schools only.
--   * New: mrr_waived / saas_mrr_waived = list-price value given away to comped/internal.
--   * get_platform_stats: tenants_by_plan = paid schools only; adds paying_tenants and
--     tenants_by_billing_mode.
--   * get_platform_revenue: by_tenant rows carry billing_mode.
-- Signatures and grants unchanged (service_role only). Down: rollback/20261021100000_*.

create or replace function lms.get_platform_stats()
returns jsonb
language plpgsql
security definer
set search_path = lms, public
as $$
declare
  v_total_tenants      int;
  v_new_tenants_30d    int;
  v_by_plan            jsonb;
  v_pending_payments   int;
  v_mrr                numeric;
  v_mrr_waived         numeric;
  v_by_mode            jsonb;
  v_paying             int;
  v_total_students     int;
  v_ref_codes          int := 0;
  v_ref_redemptions    int := 0;
begin
  select count(*) into v_total_tenants
  from tenants where status = 'active';

  select count(*) into v_paying
  from tenants where status = 'active' and billing_mode = 'paid';

  select coalesce(jsonb_object_agg(billing_mode, cnt), '{}'::jsonb) into v_by_mode
  from (select billing_mode, count(*) as cnt from tenants where status = 'active' group by billing_mode) m;

  select count(*) into v_new_tenants_30d
  from tenants where created_at >= now() - interval '30 days';

  select coalesce(jsonb_object_agg(plan, cnt), '{}'::jsonb) into v_by_plan
  from (
    select coalesce(plan, 'free') as plan, count(*) as cnt
    from tenants
    where status = 'active' and billing_mode = 'paid'
    group by coalesce(plan, 'free')
  ) p;

  select count(*) into v_pending_payments
  from platform_payment_requests where status = 'pending';

  -- MRR: only schools that actually pay (billing_mode = 'paid'). comped/internal schools
  -- hold an active platform_subscriptions row (the plan override) but pay nothing; their
  -- list-price value is reported separately as mrr_waived.
  select
    coalesce(sum(m) filter (where bm = 'paid'), 0),
    coalesce(sum(m) filter (where bm <> 'paid'), 0)
  into v_mrr, v_mrr_waived
  from (
    select t.billing_mode as bm,
      case when ps.interval = 'yearly' then pp.price_yearly / 12.0
           else pp.price_monthly end as m
    from platform_subscriptions ps
    join platform_plans pp on pp.plan_id = ps.plan_id
    join tenants t on t.id = ps.tenant_id
    where ps.status = 'active'
  ) s;

  select count(distinct user_id) into v_total_students
  from tenant_users where role = 'student';

  if to_regclass('lms.referral_codes') is not null then
    execute 'select count(*) from referral_codes' into v_ref_codes;
  end if;
  if to_regclass('lms.referral_redemptions') is not null then
    execute 'select count(*) from referral_redemptions' into v_ref_redemptions;
  end if;

  return jsonb_build_object(
    'total_tenants', coalesce(v_total_tenants, 0),
    'new_tenants_30d', coalesce(v_new_tenants_30d, 0),
    'tenants_by_plan', v_by_plan,
    'pending_payment_requests', coalesce(v_pending_payments, 0),
    'mrr_cents', round(coalesce(v_mrr, 0), 2),
    'mrr_waived', round(coalesce(v_mrr_waived, 0), 2),
    'paying_tenants', coalesce(v_paying, 0),
    'tenants_by_billing_mode', v_by_mode,
    'total_students', coalesce(v_total_students, 0),
    'total_referral_codes', v_ref_codes,
    'total_referral_redemptions', v_ref_redemptions
  );
end;
$$;

comment on function lms.get_platform_stats() is
  'Platform super-admin overview metrics across all tenants. MRR and plan distribution count paid schools only; comped/internal are reported separately (mrr_waived, tenants_by_billing_mode). Called by /platform.';

revoke all on function lms.get_platform_stats() from public, anon, authenticated;
grant execute on function lms.get_platform_stats() to service_role;

create or replace function lms.get_platform_revenue(
  _start timestamptz default null,
  _end   timestamptz default null
)
returns jsonb
language plpgsql
security definer
set search_path = lms, public
as $$
declare
  result jsonb;
  v_mrr  numeric;
  v_mrr_waived numeric;
  -- Mirror of ProviderCapabilities.bearsPlatformFee (lib/payments/types.ts).
  v_fee_bearing text[] := array['stripe', 'paypal', 'lemonsqueezy', 'binance', 'solana', 'solana_subs'];
begin
  -- SaaS MRR: paid schools only. comped/internal hold an override subscription row but pay
  -- nothing; their list-price value is reported as saas_mrr_waived.
  select
    coalesce(sum(m) filter (where bm = 'paid'), 0),
    coalesce(sum(m) filter (where bm <> 'paid'), 0)
  into v_mrr, v_mrr_waived
  from (
    select t.billing_mode as bm,
      case when ps.interval = 'yearly' then pp.price_yearly / 12.0
           else pp.price_monthly end as m
    from platform_subscriptions ps
    join platform_plans pp on pp.plan_id = ps.plan_id
    join tenants t on t.id = ps.tenant_id
    where ps.status = 'active'
  ) s;

  with tx as (
    select
      t.tenant_id,
      greatest(t.amount - coalesce(t.refunded_amount, 0), 0) as amount,
      t.transaction_date,
      coalesce(
        t.payment_provider,
        case when t.stripe_payment_intent_id is not null then 'stripe' else 'manual' end
      ) as provider,
      -- Platform share = 100 - the school's share, snapshotted per transaction.
      100 - coalesce(t.school_percentage_snapshot, lms.effective_school_percentage(t.tenant_id)) as platform_percentage
    from transactions t
    where t.status = 'successful'
      and (_start is null or t.transaction_date >= _start)
      and (_end   is null or t.transaction_date <= _end)
  ),
  tx_fee as (
    select
      tenant_id,
      amount,
      transaction_date,
      provider,
      case when provider = any(v_fee_bearing)
           then round(amount * platform_percentage / 100.0, 2)
           else 0 end as platform_fee
    from tx
  )
  select jsonb_build_object(
    'gmv',               (select coalesce(sum(amount), 0)       from tx_fee),
    'platform_fees',     (select coalesce(sum(platform_fee), 0) from tx_fee),
    'transaction_count', (select count(*)                       from tx_fee),
    'saas_mrr',          round(v_mrr, 2),
    'saas_mrr_waived',   round(coalesce(v_mrr_waived, 0), 2),
    'by_provider', (
      select coalesce(jsonb_agg(row order by row->>'fees' desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'provider', provider,
          'gmv',   round(sum(amount), 2),
          'fees',  round(sum(platform_fee), 2),
          'count', count(*)
        ) as row
        from tx_fee
        group by provider
      ) p
    ),
    'by_tenant', (
      select coalesce(jsonb_agg(row order by (row->>'fees')::numeric desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'tenant_id', tf.tenant_id,
          'name',      coalesce(tn.name, 'Unknown'),
          'plan',      coalesce(tn.plan, 'free'),
          'billing_mode', coalesce(tn.billing_mode, 'paid'),
          'gmv',   round(sum(tf.amount), 2),
          'fees',  round(sum(tf.platform_fee), 2),
          'count', count(*)
        ) as row
        from tx_fee tf
        left join tenants tn on tn.id = tf.tenant_id
        group by tf.tenant_id, tn.name, tn.plan, tn.billing_mode
      ) t
    ),
    'monthly', (
      select coalesce(jsonb_agg(row order by row->>'month'), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'month', to_char(date_trunc('month', transaction_date), 'YYYY-MM'),
          'gmv',  round(sum(amount), 2),
          'fees', round(sum(platform_fee), 2)
        ) as row
        from tx_fee
        group by date_trunc('month', transaction_date)
        order by date_trunc('month', transaction_date)
      ) m
    )
  )
  into result;

  return result;
end;
$$;

comment on function lms.get_platform_revenue(timestamptz, timestamptz) is
  'Platform super-admin revenue/fees across all tenants: GMV net of refunds, computed platform fees, SaaS MRR (paid schools only) plus waived value of comped/internal, and by-provider/by-tenant/monthly breakdowns. Called by /platform/revenue.';

revoke all on function lms.get_platform_revenue(timestamptz, timestamptz) from public, anon, authenticated;
grant execute on function lms.get_platform_revenue(timestamptz, timestamptz) to service_role;

-- ===========================================================================
-- 20261022120001_drop_unenforced_enrollment_settings.sql
-- ===========================================================================
-- These tenant_settings keys had a form and an MCP field but no reader anywhere
-- (access and its expiry live on `entitlements`). Drop the orphan rows.
DELETE FROM tenant_settings
WHERE setting_key IN (
  'auto_enrollment',
  'allow_self_enrollment',
  'require_enrollment_approval',
  'max_enrollments_per_user',
  'enrollment_expiration_days',
  'course_capacity_enabled'
);

-- ===========================================================================
-- 20261022130000_tenant_assets.sql
-- ===========================================================================
-- Tenant asset library: one row per file a school has uploaded to a public
-- content bucket (course covers, landing-page images, certificate logos and
-- signatures, community media, AI-generated images).
--
-- Uploads came from five server actions, the MCP server and client-side code,
-- none of which recorded anything, so a school could not see or reuse what it
-- had uploaded. A trigger on storage.objects is the one place every path
-- passes (service role, user JWT, MCP), so the table cannot drift from the
-- buckets. The first path segment of every tracked object is the tenant id.

CREATE TABLE IF NOT EXISTS lms.tenant_assets (
  asset_id    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL REFERENCES lms.tenants(id) ON DELETE CASCADE,
  bucket      text NOT NULL,
  path        text NOT NULL,
  name        text NOT NULL,
  mime_type   text,
  size_bytes  bigint,
  kind        text NOT NULL DEFAULT 'other' CHECK (kind IN ('image', 'video', 'document', 'other')),
  source      text NOT NULL DEFAULT 'other' CHECK (source IN
                ('course', 'landing_page', 'certificate', 'community', 'ai_generated', 'library', 'other')),
  uploaded_by uuid,
  created_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (bucket, path)
);

CREATE INDEX IF NOT EXISTS tenant_assets_tenant_created_idx
  ON lms.tenant_assets (tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS tenant_assets_tenant_kind_idx
  ON lms.tenant_assets (tenant_id, kind, source);

ALTER TABLE lms.tenant_assets ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Staff read the school's assets" ON lms.tenant_assets;
CREATE POLICY "Staff read the school's assets"
  ON lms.tenant_assets FOR SELECT TO authenticated
  USING (lms.is_staff_of(tenant_id));

-- Rows are written only by the storage trigger below (definer) and the service role.

-- ---------------------------------------------------------------------------
-- Storage INSERT policies: staff of the folder's own school only
-- ---------------------------------------------------------------------------
-- The old policies let ANY authenticated user write anywhere in the bucket
-- (the server actions were the only gate). The library uploads straight from
-- the browser, so the policy itself must pin the first folder to the caller's
-- school. Server actions and the MCP server keep working: the former use the
-- service role, the latter uploads as a staff user into its own tenant folder.
DROP POLICY IF EXISTS "Authenticated users can upload course images" ON storage.objects;
DROP POLICY IF EXISTS "Tenant admins can upload landing page assets" ON storage.objects;
DROP POLICY IF EXISTS "Staff upload into their school folder" ON storage.objects;
CREATE POLICY "Staff upload into their school folder"
  ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (
    bucket_id IN ('course-images', 'landing-page-assets')
    AND (storage.foldername(name))[1] ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    AND lms.is_staff_of(((storage.foldername(name))[1])::uuid)
  );

-- ---------------------------------------------------------------------------
-- Trigger: mirror storage.objects of the tracked buckets
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION lms.sync_tenant_asset()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  _tenant   uuid;
  _mime     text;
  _kind     text;
  _source   text;
  _segments text[];
BEGIN
  BEGIN
    IF TG_OP = 'DELETE' THEN
      DELETE FROM lms.tenant_assets WHERE bucket = OLD.bucket_id AND path = OLD.name;
      RETURN OLD;
    END IF;

    IF NEW.bucket_id NOT IN ('course-images', 'landing-page-assets', 'community-assets') THEN
      RETURN NEW;
    END IF;

    _segments := string_to_array(NEW.name, '/');
    IF _segments[1] !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RETURN NEW;
    END IF;
    _tenant := _segments[1]::uuid;
    IF NOT EXISTS (SELECT 1 FROM lms.tenants WHERE id = _tenant) THEN
      RETURN NEW;
    END IF;

    _mime := NEW.metadata ->> 'mimetype';
    _kind := CASE
      WHEN _mime LIKE 'image/%' OR NEW.name ~* '\.(jpe?g|png|gif|webp|svg)$' THEN 'image'
      WHEN _mime LIKE 'video/%' OR NEW.name ~* '\.(mp4|webm|mov)$' THEN 'video'
      WHEN _mime = 'application/pdf' OR NEW.name ~* '\.pdf$' THEN 'document'
      ELSE 'other'
    END;
    _source := CASE
      WHEN NEW.bucket_id = 'community-assets' THEN 'community'
      WHEN NEW.bucket_id = 'landing-page-assets' AND _segments[2] = 'certificates' THEN 'certificate'
      WHEN NEW.bucket_id = 'landing-page-assets' AND _segments[2] = 'library' THEN 'library'
      WHEN NEW.bucket_id = 'landing-page-assets' THEN 'landing_page'
      WHEN NEW.bucket_id = 'course-images' AND _segments[2] IS NOT NULL
           AND array_length(_segments, 1) > 2 THEN 'ai_generated'
      WHEN NEW.bucket_id = 'course-images' THEN 'course'
      ELSE 'other'
    END;

    INSERT INTO lms.tenant_assets
      (tenant_id, bucket, path, name, mime_type, size_bytes, kind, source, uploaded_by, created_at)
    VALUES (
      _tenant, NEW.bucket_id, NEW.name, _segments[array_length(_segments, 1)], _mime,
      NULLIF(NEW.metadata ->> 'size', '')::bigint, _kind, _source, NEW.owner,
      COALESCE(NEW.created_at, now())
    )
    ON CONFLICT (bucket, path) DO UPDATE
      SET mime_type  = COALESCE(EXCLUDED.mime_type, lms.tenant_assets.mime_type),
          size_bytes = COALESCE(EXCLUDED.size_bytes, lms.tenant_assets.size_bytes),
          kind       = EXCLUDED.kind;
  EXCEPTION WHEN OTHERS THEN
    -- Bookkeeping must never be the reason an upload or delete fails.
    RAISE WARNING 'sync_tenant_asset failed: %', SQLERRM;
  END;
  RETURN COALESCE(NEW, OLD);
END;
$$;

REVOKE ALL ON FUNCTION lms.sync_tenant_asset() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS tenant_assets_sync_ins ON storage.objects;
CREATE TRIGGER tenant_assets_sync_ins
  AFTER INSERT OR UPDATE OF metadata ON storage.objects
  FOR EACH ROW EXECUTE FUNCTION lms.sync_tenant_asset();

DROP TRIGGER IF EXISTS tenant_assets_sync_del ON storage.objects;
CREATE TRIGGER tenant_assets_sync_del
  AFTER DELETE ON storage.objects
  FOR EACH ROW EXECUTE FUNCTION lms.sync_tenant_asset();

-- ---------------------------------------------------------------------------
-- Backfill what already exists
-- ---------------------------------------------------------------------------
INSERT INTO lms.tenant_assets
  (tenant_id, bucket, path, name, mime_type, size_bytes, kind, source, uploaded_by, created_at)
SELECT
  t.id, o.bucket_id, o.name,
  (string_to_array(o.name, '/'))[array_length(string_to_array(o.name, '/'), 1)],
  o.metadata ->> 'mimetype',
  NULLIF(o.metadata ->> 'size', '')::bigint,
  CASE
    WHEN o.metadata ->> 'mimetype' LIKE 'image/%' OR o.name ~* '\.(jpe?g|png|gif|webp|svg)$' THEN 'image'
    WHEN o.metadata ->> 'mimetype' LIKE 'video/%' OR o.name ~* '\.(mp4|webm|mov)$' THEN 'video'
    WHEN o.name ~* '\.pdf$' THEN 'document'
    ELSE 'other'
  END,
  CASE
    WHEN o.bucket_id = 'community-assets' THEN 'community'
    WHEN o.bucket_id = 'landing-page-assets' AND o.name LIKE '%/certificates/%' THEN 'certificate'
    WHEN o.bucket_id = 'landing-page-assets' AND o.name LIKE '%/library/%' THEN 'library'
    WHEN o.bucket_id = 'landing-page-assets' THEN 'landing_page'
    WHEN o.bucket_id = 'course-images'
         AND array_length(string_to_array(o.name, '/'), 1) > 2 THEN 'ai_generated'
    ELSE 'course'
  END,
  o.owner,
  COALESCE(o.created_at, now())
FROM storage.objects o
JOIN lms.tenants t
  ON o.name ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/'
 AND t.id = (string_to_array(o.name, '/'))[1]::uuid
WHERE o.bucket_id IN ('course-images', 'landing-page-assets', 'community-assets')
  AND o.name NOT LIKE '%/.emptyFolderPlaceholder'
ON CONFLICT (bucket, path) DO NOTHING;

-- ===========================================================================
-- 20261022130001_allow_library_browser_upload.sql
-- ===========================================================================
-- The asset library (upstream #999) uploads from the browser into
-- landing-page-assets/<school>/library/. The restrictive insert policy from
-- 20261022120000_storage_security_hardening.sql blocks every browser insert into that
-- bucket, so the upload failed. Allow browser inserts into the library folder only;
-- every other path in these buckets stays server-only.
--
-- A restrictive policy still has to pass, and the permissive "Staff upload into their
-- school folder" policy (20261022130000_tenant_assets.sql) still pins the first folder to a
-- school the caller is staff of. Bucket size and MIME limits still apply. Trade-off: library
-- uploads skip the server-side content check that app/actions/storage.ts performs.
DROP POLICY IF EXISTS "App storage writes require trusted server insert" ON storage.objects;
CREATE POLICY "App storage writes require trusted server insert" ON storage.objects
AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (
  bucket_id NOT IN ('payment-proofs', 'landing-page-assets', 'course-images', 'community-assets',
                   'certificates', 'exercise-media', 'lesson-resources', 'ai-chat-attachments', 'avatars')
  OR (bucket_id = 'landing-page-assets' AND (storage.foldername(name))[2] = 'library')
);

-- ===========================================================================
-- 20261022131000_lock_access_grant_paths.sql
-- ===========================================================================
-- Access-grant hardening (audit 2026-10-22).
-- Course access may only be created by: the transaction trigger (server-written
-- 'successful' rows), grant_free_*/self_enroll_* RPCs (they validate the caller),
-- or service-role code. None of those need these functions open to clients.

-- 1. enroll_user / handle_new_subscription are SECURITY DEFINER with no caller,
--    tenant or payment check. They were executable by anon/authenticated:
--    rpc('enroll_user', { _user_id, _product_id }) granted any product's courses.
REVOKE ALL ON FUNCTION lms.enroll_user(uuid, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.enroll_user(uuid, integer) TO service_role;

REVOKE ALL ON FUNCTION lms.handle_new_subscription(uuid, integer, integer, timestamptz)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.handle_new_subscription(uuid, integer, integer, timestamptz)
  TO service_role;

-- The transaction trigger is the legitimate caller and fires as whoever wrote the
-- row (a staff session approving a payment is not service_role). Run it as its
-- owner so the revokes above never break a purchase.
ALTER FUNCTION lms.trigger_manage_transactions() SECURITY DEFINER;
ALTER FUNCTION lms.trigger_manage_transactions() SET search_path = '';
REVOKE ALL ON FUNCTION lms.trigger_manage_transactions() FROM PUBLIC, anon, authenticated;

-- 2. A student could INSERT their own 'active' subscription (any plan, any end
--    date) and then call self_enroll_subscription_course. Subscriptions are
--    written only by server code and SECURITY DEFINER RPCs.
DROP POLICY IF EXISTS "Users can create own subscriptions" ON lms.subscriptions;

-- 3. Defence in depth: RLS already blocks client writes to entitlements, so the
--    table grants must not be the only thing standing in the way.
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON lms.entitlements FROM anon, authenticated;
REVOKE ALL ON lms.payment_requests FROM anon;

-- 4. Reads that ignored the access gate.
-- lessons_ai_tasks (system prompts) and lessons_ai_task_messages (every student's
-- chat) had USING (true) for role public: anon, any tenant.
DROP POLICY IF EXISTS "Enable read access for all users" ON lms.lessons_ai_tasks;
DROP POLICY IF EXISTS "Public read access for tasks" ON lms.lessons_ai_tasks;
CREATE POLICY lessons_ai_tasks_select ON lms.lessons_ai_tasks
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM lms.lessons l
    WHERE l.id = lessons_ai_tasks.lesson_id
      AND (lms.is_staff_of(l.tenant_id)
           OR lms.has_course_access((SELECT auth.uid()), l.course_id::integer))
  ));

DROP POLICY IF EXISTS "Enable read access for all users" ON lms.lessons_ai_task_messages;

DROP POLICY IF EXISTS "Authenticated users can view exercise files" ON lms.exercise_files;
CREATE POLICY exercise_files_select ON lms.exercise_files
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM lms.exercises x
    WHERE x.id = exercise_files.exercise_id
      AND (lms.is_staff_of(x.tenant_id)
           OR lms.has_course_access((SELECT auth.uid()), x.course_id::integer))
  ));

-- ===========================================================================
-- 20261022140000_content_read_gates.sql
-- ===========================================================================
-- Content-read gates (security audit follow-up).
--
-- 1. lessons: the authenticated preview branch now honours the school's
--    `free_preview_enabled` switch (same expression as the anon policy in
--    20260920130000). Missing row = ON.
-- 2. lessons / exams / exercises: the entitled (has_course_access) branch only
--    sees PUBLISHED rows (lessons also: publish_at null or past). Staff of the
--    tenant (is_tenant_staff) and the course author keep seeing drafts.
-- 3. storage `payment-proofs`: SELECT scoped to the uploader, staff of the
--    owning tenant, and super admins (was: any logged-in user).
--
-- Path layout (see app/actions/payment-requests.ts, app/actions/admin/billing.ts):
--   student/{tenant_id}/{user_id}/{request_id}/proof.ext   (student upload)
--   platform/{tenant_id}/{request_id}/proof.ext            (school admin upload)

-- ---------------------------------------------------------------- lessons
DROP POLICY IF EXISTS "Users can view tenant lessons" ON lms.lessons;

CREATE POLICY "Users can view tenant lessons" ON lms.lessons
  FOR SELECT TO authenticated
  USING (
    tenant_id = (SELECT lms.get_tenant_id())
    AND (
      -- staff of this tenant: everything, drafts included
      (SELECT lms.is_tenant_staff())
      -- course author: everything in their course
      OR EXISTS (
        SELECT 1 FROM lms.courses c
        WHERE c.course_id = lessons.course_id
          AND c.author_id = (SELECT auth.uid())
      )
      -- entitled student: published and already live
      OR (
        status = 'published'
        AND (publish_at IS NULL OR publish_at <= now())
        AND lms.has_course_access((SELECT auth.uid()), lessons.course_id::integer)
      )
      -- free preview, only while the school switch is on
      OR (
        is_preview = true
        AND status = 'published'
        AND (publish_at IS NULL OR publish_at <= now())
        AND COALESCE(
          (
            SELECT (ts.setting_value ->> 'enabled')::boolean
            FROM lms.tenant_settings ts
            WHERE ts.tenant_id = (SELECT lms.get_tenant_id())
              AND ts.setting_key = 'free_preview_enabled'
          ),
          true
        )
        AND EXISTS (
          SELECT 1 FROM lms.courses c
          WHERE c.course_id = lessons.course_id
            AND c.status = 'published'
            AND c.tenant_id = lessons.tenant_id
        )
      )
    )
  );

-- ------------------------------------------------------------------ exams
DROP POLICY IF EXISTS "Students can view tenant exams" ON lms.exams;

CREATE POLICY "Students can view tenant exams" ON lms.exams
  FOR SELECT TO authenticated
  USING (
    tenant_id = (SELECT lms.get_tenant_id())
    AND (
      (SELECT lms.is_tenant_staff())
      OR EXISTS (
        SELECT 1 FROM lms.courses c
        WHERE c.course_id = exams.course_id
          AND c.author_id = (SELECT auth.uid())
      )
      OR (
        status = 'published'
        AND lms.has_course_access((SELECT auth.uid()), exams.course_id)
      )
    )
  );

-- -------------------------------------------------------------- exercises
DROP POLICY IF EXISTS "Users can view tenant exercises" ON lms.exercises;

CREATE POLICY "Users can view tenant exercises" ON lms.exercises
  FOR SELECT TO authenticated
  USING (
    tenant_id = (SELECT lms.get_tenant_id())
    AND (
      (SELECT lms.is_tenant_staff())
      OR EXISTS (
        SELECT 1 FROM lms.courses c
        WHERE c.course_id = exercises.course_id
          AND c.author_id = (SELECT auth.uid())
      )
      OR (
        status = 'published'
        AND lms.has_course_access((SELECT auth.uid()), exercises.course_id)
      )
    )
  );

-- ---------------------------------------------------------- payment-proofs
DROP POLICY IF EXISTS "Users read payment proofs" ON storage.objects;

CREATE POLICY "Users read payment proofs" ON storage.objects
  FOR SELECT TO authenticated
  USING (
    bucket_id = 'payment-proofs'
    AND (
      -- uploader (also covers createSignedUrl right after upload)
      owner_id = (SELECT auth.uid())::text
      OR (SELECT lms.is_super_admin())
      -- student/{tenant}/{user}/...: the student themself
      OR (
        (storage.foldername(name))[1] = 'student'
        AND (storage.foldername(name))[3] = (SELECT auth.uid())::text
      )
      -- student/{tenant}/...: active teacher/admin of that tenant
      OR (
        (storage.foldername(name))[1] = 'student'
        AND EXISTS (
          SELECT 1 FROM lms.tenant_users tu
          WHERE tu.user_id = (SELECT auth.uid())
            AND tu.tenant_id::text = (storage.foldername(name))[2]
            AND tu.status = 'active'
            AND tu.role::text IN ('teacher', 'admin')
        )
      )
      -- platform/{tenant}/...: active admin of that tenant
      OR (
        (storage.foldername(name))[1] = 'platform'
        AND EXISTS (
          SELECT 1 FROM lms.tenant_users tu
          WHERE tu.user_id = (SELECT auth.uid())
            AND tu.tenant_id::text = (storage.foldername(name))[2]
            AND tu.status = 'active'
            AND tu.role::text = 'admin'
        )
      )
    )
  );

-- ===========================================================================
-- 20261022150000_sync_enrollment_status_with_entitlements.sql
-- ===========================================================================
-- Keep enrollments.status in step with entitlements (the source of truth for access).
--
-- When a user's LAST live entitlement for a course ends, the enrollment becomes
-- 'disabled'; when any entitlement is live again it returns to 'active'.
-- "Live" = status = 'active' AND (expires_at IS NULL OR expires_at > now()),
-- the same predicate has_course_access() uses (tenant access cutoff excluded:
-- it is tenant-wide and reversible, and has no trigger to hang this on).
--
-- Notes:
--   * Only touches EXISTING enrollment rows. It never creates one (enroll_user,
--     grant_free_entitlement and self_enroll_subscription_course still do, and
--     insert the entitlement first, so the first trigger run is a no-op).
--   * Time passing (expires_at) fires nothing; readers apply the expiry check.
--   * No DELETE trigger: entitlement deletes only happen via cascades (user /
--     course / tenant deletion) where the enrollment goes with them.
--   * Idempotent: UPDATE only when the value actually changes.

CREATE OR REPLACE FUNCTION lms.sync_enrollment_status_from_entitlements()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  _live boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM lms.entitlements AS e
    WHERE e.user_id = NEW.user_id
      AND e.course_id = NEW.course_id
      AND e.status = 'active'
      AND (e.expires_at IS NULL OR e.expires_at > now())
  ) INTO _live;

  IF _live THEN
    UPDATE lms.enrollments AS en
    SET status = 'active'
    WHERE en.user_id = NEW.user_id
      AND en.course_id = NEW.course_id
      AND en.status IS DISTINCT FROM 'active';
  ELSE
    UPDATE lms.enrollments AS en
    SET status = 'disabled'
    WHERE en.user_id = NEW.user_id
      AND en.course_id = NEW.course_id
      AND en.status = 'active';
  END IF;

  RETURN NULL; -- AFTER trigger
END;
$$;

REVOKE ALL ON FUNCTION lms.sync_enrollment_status_from_entitlements() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS trg_sync_enrollment_status_ins ON lms.entitlements;
CREATE TRIGGER trg_sync_enrollment_status_ins
  AFTER INSERT ON lms.entitlements
  FOR EACH ROW
  EXECUTE FUNCTION lms.sync_enrollment_status_from_entitlements();

DROP TRIGGER IF EXISTS trg_sync_enrollment_status_upd ON lms.entitlements;
CREATE TRIGGER trg_sync_enrollment_status_upd
  AFTER UPDATE OF status, expires_at ON lms.entitlements
  FOR EACH ROW
  WHEN (OLD.status IS DISTINCT FROM NEW.status OR OLD.expires_at IS DISTINCT FROM NEW.expires_at)
  EXECUTE FUNCTION lms.sync_enrollment_status_from_entitlements();

-- One-time backfill: enrollments that already lapsed. Restricted to users who
-- HAVE entitlement rows for the course, none of them live, so legacy
-- enrollments with no entitlement history are left alone.
UPDATE lms.enrollments AS en
SET status = 'disabled'
WHERE en.status = 'active'
  AND EXISTS (
    SELECT 1 FROM lms.entitlements AS e
    WHERE e.user_id = en.user_id AND e.course_id = en.course_id
  )
  AND NOT EXISTS (
    SELECT 1 FROM lms.entitlements AS e
    WHERE e.user_id = en.user_id AND e.course_id = en.course_id
      AND e.status = 'active'
      AND (e.expires_at IS NULL OR e.expires_at > now())
  );

-- ===========================================================================
-- 20261022160000_free_grant_excludes_plan_courses.sql
-- ===========================================================================
-- Security audit: "free" must not mean "has no product".
--
-- 1. A course sold ONLY through a plan (rows in plan_courses, no product_courses)
--    passed the old "no linked product with price <> 0" test, so any active
--    member could self-enroll it for free through grant_free_entitlement().
--    The function now also refuses a course that belongs to any non-deleted,
--    priced (price > 0) plan of the tenant. Courses/plans that are genuinely
--    free (no product, no plan, or only price-0 ones) keep working.
--
-- 2. ON CONFLICT DO UPDATE re-activated a free entitlement that staff had
--    revoked, handing access back on the next click. Rule: a 'free'
--    entitlement with status 'revoked' is final for self-service; only staff
--    (admin grant / delete the revoked row) can restore it. There is no
--    student self-revoke path for free entitlements, and status 'expired'
--    free rows remain re-grantable. Existing active rows stay idempotent.
--
-- grant_free_subscription() already pins plan price = 0 and deleted_at IS NULL
-- server-side, so it needs no change. Signature, SECURITY DEFINER, empty
-- search_path and the EXECUTE grants (authenticated only) are unchanged.

CREATE OR REPLACE FUNCTION lms.grant_free_entitlement(_user_id uuid, _course_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    _caller_id uuid := auth.uid();
    _tenant_id uuid;
BEGIN
    IF _caller_id IS NULL OR _caller_id <> _user_id THEN
        RAISE EXCEPTION 'Free enrollment can only be granted to the authenticated user';
    END IF;

    SELECT c.tenant_id
    INTO _tenant_id
    FROM lms.courses AS c
    WHERE c.course_id = _course_id
      AND c.status = 'published';

    IF _tenant_id IS NULL THEN
        RAISE EXCEPTION 'Course is not available for enrollment';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM lms.tenant_users AS tu
        WHERE tu.user_id = _caller_id
          AND tu.tenant_id = _tenant_id
          AND tu.status = 'active'
    ) THEN
        RAISE EXCEPTION 'User is not an active member of this tenant';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM lms.product_courses AS pc
        JOIN lms.products AS p
          ON p.product_id = pc.product_id
         AND p.tenant_id = pc.tenant_id
        WHERE pc.course_id = _course_id
          AND pc.tenant_id = _tenant_id
          AND p.price <> 0
    ) THEN
        RAISE EXCEPTION 'This course requires payment';
    END IF;

    -- A course sold only through a priced plan is not free either.
    IF EXISTS (
        SELECT 1
        FROM lms.plan_courses AS plc
        JOIN lms.plans AS pl
          ON pl.plan_id = plc.plan_id
        WHERE plc.course_id = _course_id
          AND pl.tenant_id = _tenant_id
          AND pl.deleted_at IS NULL
          AND pl.price > 0
    ) THEN
        RAISE EXCEPTION 'This course requires payment';
    END IF;

    -- Staff-revoked free access is not self-service re-grantable.
    IF EXISTS (
        SELECT 1
        FROM lms.entitlements AS e
        WHERE e.user_id = _caller_id
          AND e.course_id = _course_id
          AND e.source_type = 'free'
          AND e.status = 'revoked'
    ) THEN
        RAISE EXCEPTION 'Access to this course was revoked';
    END IF;

    -- #929 fee gate: no NEW free enrollment while the school's sales are blocked.
    IF NOT lms.free_enrollment_allowed(_tenant_id, _caller_id, _course_id) THEN
        RAISE EXCEPTION 'sales_blocked:fees' USING ERRCODE = 'LM003';
    END IF;

    INSERT INTO lms.entitlements (
        user_id,
        course_id,
        tenant_id,
        source_type,
        source_id,
        status,
        expires_at
    )
    VALUES (_caller_id, _course_id, _tenant_id, 'free', NULL, 'active', NULL)
    ON CONFLICT (user_id, course_id, source_type, source_id) DO UPDATE SET
        status = 'active',
        revoked_at = NULL,
        tenant_id = EXCLUDED.tenant_id
    WHERE lms.entitlements.status <> 'revoked';

    INSERT INTO lms.enrollments (
        user_id,
        course_id,
        enrollment_date,
        status,
        tenant_id
    )
    VALUES (_caller_id, _course_id, NOW(), 'active', _tenant_id)
    ON CONFLICT (user_id, course_id) DO UPDATE SET
        status = 'active',
        tenant_id = EXCLUDED.tenant_id;
END;
$function$;

-- Supabase default privileges also grant EXECUTE to anon; the body already
-- rejects a NULL auth.uid(), but an unauthenticated role has no business here.
REVOKE EXECUTE ON FUNCTION lms.grant_free_entitlement(uuid, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION lms.grant_free_entitlement(uuid, integer) TO authenticated;

-- ===========================================================================
-- 20261022170000_hide_lesson_ai_system_prompt.sql
-- ===========================================================================
-- The teacher's private tutor prompt (lessons_ai_tasks.system_prompt) was readable
-- by every entitled student: RLS is row-level, so `select('*')` / `select=system_prompt`
-- returned it. Filtering on it (`system_prompt=ilike.*x*`) was also an oracle.
--
-- Fix at the privilege layer: clients lose SELECT on the column. Everything that
-- needs the prompt goes through
--   * the server tutor (service role, which keeps its grants), or
--   * lms.get_lesson_ai_system_prompt() for the lesson's staff / course author.
--
-- INSERT / UPDATE / DELETE grants are untouched, so teachers keep writing the prompt
-- through RLS-scoped writes. NOTE: a client write that RETURNS the row (`.select()`
-- after upsert/insert) now has to name columns and leave system_prompt out.
--
-- New columns are NOT readable by clients until granted here on purpose (allow-list).

REVOKE SELECT ON lms.lessons_ai_tasks FROM anon, authenticated;

GRANT SELECT (id, created_at, lesson_id, task_instructions, requirements)
  ON lms.lessons_ai_tasks TO authenticated;

CREATE OR REPLACE FUNCTION lms.get_lesson_ai_system_prompt(_lesson_id bigint)
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT t.system_prompt
  FROM lms.lessons_ai_tasks t
  JOIN lms.lessons l ON l.id = t.lesson_id
  JOIN lms.courses c ON c.course_id = l.course_id
  WHERE t.lesson_id = _lesson_id
    AND (
      lms.is_staff_of(l.tenant_id)
      OR c.author_id = (SELECT auth.uid())
    );
$$;

REVOKE ALL ON FUNCTION lms.get_lesson_ai_system_prompt(bigint) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION lms.get_lesson_ai_system_prompt(bigint) TO authenticated, service_role;

-- `INSERT ... ON CONFLICT DO UPDATE SET system_prompt = EXCLUDED.system_prompt`
-- (what PostgREST upsert emits) needs SELECT on the column, which clients no
-- longer have. Writing the task therefore goes through this function, with the
-- same authorization as the read: staff of the lesson's tenant or the course author.
CREATE OR REPLACE FUNCTION lms.upsert_lesson_ai_task(
  _lesson_id bigint,
  _task_instructions text,
  _system_prompt text,
  _requirements jsonb DEFAULT NULL
)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  _id bigint;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM lms.lessons l
    JOIN lms.courses c ON c.course_id = l.course_id
    WHERE l.id = _lesson_id
      AND (lms.is_staff_of(l.tenant_id) OR c.author_id = (SELECT auth.uid()))
  ) THEN
    RAISE EXCEPTION 'Not authorized to edit this lesson''s AI task' USING ERRCODE = '42501';
  END IF;

  INSERT INTO lms.lessons_ai_tasks (lesson_id, task_instructions, system_prompt, requirements)
  VALUES (_lesson_id, _task_instructions, _system_prompt, _requirements)
  ON CONFLICT (lesson_id) DO UPDATE SET
    task_instructions = EXCLUDED.task_instructions,
    system_prompt = EXCLUDED.system_prompt,
    requirements = EXCLUDED.requirements
  RETURNING id INTO _id;

  RETURN _id;
END;
$$;

REVOKE ALL ON FUNCTION lms.upsert_lesson_ai_task(bigint, text, text, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION lms.upsert_lesson_ai_task(bigint, text, text, jsonb) TO authenticated, service_role;

-- ===========================================================================
-- 20261022180000_payment_proofs_insert_scope.sql
-- ===========================================================================
-- "Users upload payment proofs" let any logged-in user write ANY path in the
-- bucket (e.g. over another tenant's proof, or plant files under a tenant they
-- do not belong to). Path layout (app/actions/payment-requests.ts, admin/billing.ts):
--   student/{tenant_id}/{user_id}/{request_id}/proof.ext   student, active member
--   platform/{tenant_id}/{request_id}/proof.ext            active admin of that tenant
DROP POLICY IF EXISTS "Users upload payment proofs" ON storage.objects;

CREATE POLICY "Users upload payment proofs" ON storage.objects
  FOR INSERT TO authenticated
  WITH CHECK (
    bucket_id = 'payment-proofs'
    AND (
      (
        (storage.foldername(name))[1] = 'student'
        AND (storage.foldername(name))[3] = (SELECT auth.uid())::text
        AND EXISTS (
          SELECT 1 FROM lms.tenant_users tu
          WHERE tu.user_id = (SELECT auth.uid())
            AND tu.tenant_id::text = (storage.foldername(name))[2]
            AND tu.status = 'active'
        )
      )
      OR (
        (storage.foldername(name))[1] = 'platform'
        AND EXISTS (
          SELECT 1 FROM lms.tenant_users tu
          WHERE tu.user_id = (SELECT auth.uid())
            AND tu.tenant_id::text = (storage.foldername(name))[2]
            AND tu.status = 'active'
            AND tu.role::text = 'admin'
        )
      )
    )
  );

-- ===========================================================================
-- 20261022190000_invitation_token.sql
-- ===========================================================================
-- Invitations are consumed by SECRET TOKEN, not by email match.
--
-- Until now `joinSchool` accepted a pending invitation for anyone whose
-- account email equalled the invited address. Sign-up does not require a
-- verified email, so whoever registered the invitee's address first captured
-- the invited role (teacher). The invitation now carries an unguessable token
-- that only travels in the emailed / shared link (`/join-school?invite=<token>`),
-- and an invitation is consumed only when the token AND the account email match.
--
-- Breaking by design: invitations that are pending today get a token nobody has
-- received, so they are unusable until the admin invites again (re-inviting a
-- pending address rotates its token).

-- 128+ bits of CSPRNG output without depending on pgcrypto's schema:
-- gen_random_uuid() is core Postgres (13+). Two v4 UUIDs, dashes stripped.
ALTER TABLE lms.tenant_invitations
  ADD COLUMN IF NOT EXISTS token text NOT NULL
    DEFAULT replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
  ADD COLUMN IF NOT EXISTS expires_at timestamptz NOT NULL
    DEFAULT (now() + interval '14 days');

CREATE UNIQUE INDEX IF NOT EXISTS tenant_invitations_token_key
  ON lms.tenant_invitations (token);

-- `UNIQUE (tenant_id, email, status)` meant a second *accepted* (or expired)
-- row for the same address violated the constraint, which silently broke the
-- bookkeeping UPDATE on a re-invite. The intent was only "one PENDING invite
-- per email per tenant".
ALTER TABLE lms.tenant_invitations
  DROP CONSTRAINT IF EXISTS tenant_invitations_tenant_id_email_status_key;

CREATE UNIQUE INDEX IF NOT EXISTS tenant_invitations_one_pending_per_email
  ON lms.tenant_invitations (tenant_id, email)
  WHERE status = 'pending';

-- RLS is unchanged and is what keeps tokens private: the only policies on this
-- table are "tenant admins manage their own tenant's rows" and service_role.
-- Students, teachers and the invitee themself cannot SELECT a token.
-- (anon/authenticated still hold table GRANTs, as everywhere in this schema;
-- with RLS enabled and no matching policy they see zero rows.)

-- ===========================================================================
-- 20261022200000_drop_lessons_ai_task_instructions.sql
-- ===========================================================================
-- Drop the legacy lessons.ai_task_instructions column.
--
-- The teacher's private AI-tutor prompt lives in lessons_ai_tasks.system_prompt
-- (hidden from students by 20261022170000). The legacy lessons column was still
-- readable by any entitled student through `select *` on lessons, and a version
-- restore kept writing to it. Breaking cleanup, approved: drop the column.
--
-- Deploy order: nothing in the app reads or writes the column any more, so
-- migrate before or after the code; only a stale client that still names it in
-- a select would error ("column does not exist").

-- 1. Keep any prompt that only exists in the legacy column. Never overwrite an
--    existing non-empty lessons_ai_tasks.system_prompt.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'lms' AND table_name = 'lessons'
      AND column_name = 'ai_task_instructions'
  ) THEN
    UPDATE lms.lessons_ai_tasks t
       SET system_prompt = l.ai_task_instructions
      FROM lms.lessons l
     WHERE t.lesson_id = l.id
       AND btrim(coalesce(l.ai_task_instructions, '')) <> ''
       AND btrim(coalesce(t.system_prompt, '')) = '';

    INSERT INTO lms.lessons_ai_tasks (lesson_id, system_prompt)
    SELECT l.id, l.ai_task_instructions
      FROM lms.lessons l
     WHERE btrim(coalesce(l.ai_task_instructions, '')) <> ''
       AND NOT EXISTS (SELECT 1 FROM lms.lessons_ai_tasks t WHERE t.lesson_id = l.id);
  END IF;
END $$;

-- 2. Functions that referenced the column (latest definitions: 20260302180000
--    snapshot trigger, 20260729120000 restore), minus the column.
CREATE OR REPLACE FUNCTION lms.snapshot_lesson_version()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms, public
AS $$
DECLARE
  _snapshot JSONB;
  _ai_task JSONB;
BEGIN
  SELECT jsonb_build_object(
    'id', lat.id,
    'system_prompt', lat.system_prompt,
    'task_instructions', lat.task_instructions
  ) INTO _ai_task
  FROM lessons_ai_tasks lat
  WHERE lat.lesson_id = OLD.id;

  _snapshot := jsonb_build_object(
    'id', OLD.id,
    'course_id', OLD.course_id,
    'sequence', OLD.sequence,
    'title', OLD.title,
    'content', OLD.content,
    'description', OLD.description,
    'summary', OLD.summary,
    'video_url', OLD.video_url,
    'embed_code', OLD.embed_code,
    'status', OLD.status,
    'image', OLD.image,
    'ai_task_description', OLD.ai_task_description,
    'ai_task', _ai_task,
    'updated_at', OLD.updated_at
  );

  INSERT INTO content_versions (content_type, content_id, version_number, snapshot, changed_by)
  VALUES ('lesson', OLD.id, next_version_number('lesson', OLD.id), _snapshot, auth.uid());

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION lms.restore_lesson_version(_lesson_id bigint, _version_number integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'lms', 'public'
AS $function$
DECLARE
  _snap JSONB;
  _ai_task JSONB;
BEGIN
  -- Auth check: caller must be the course author
  IF NOT EXISTS (
    SELECT 1 FROM lessons l
    JOIN courses c ON c.course_id = l.course_id
    WHERE l.id = _lesson_id AND c.author_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized to restore this lesson';
  END IF;

  -- Fetch snapshot
  SELECT snapshot INTO _snap
  FROM content_versions
  WHERE content_type = 'lesson' AND content_id = _lesson_id AND version_number = _version_number;

  IF _snap IS NULL THEN
    RAISE EXCEPTION 'Version not found';
  END IF;

  -- Update lesson (triggers snapshot of current state)
  UPDATE lessons SET
    title = _snap->>'title',
    content = _snap->>'content',
    description = _snap->>'description',
    summary = _snap->>'summary',
    video_url = _snap->>'video_url',
    embed_code = _snap->>'embed_code',
    status = (_snap->>'status')::status,
    image = _snap->>'image',
    ai_task_description = _snap->>'ai_task_description',
    updated_at = NOW()
  WHERE id = _lesson_id;

  _ai_task := _snap->'ai_task';
  IF _ai_task IS NOT NULL AND _ai_task != 'null'::jsonb THEN
    INSERT INTO lessons_ai_tasks (lesson_id, system_prompt, task_instructions)
    VALUES (
      _lesson_id,
      _ai_task->>'system_prompt',
      _ai_task->>'task_instructions'
    )
    ON CONFLICT (lesson_id) DO UPDATE SET
      system_prompt = EXCLUDED.system_prompt,
      task_instructions = EXCLUDED.task_instructions;
  ELSIF _snap ? 'ai_task' THEN
    -- The snapshot knows about the task and records that there was none.
    DELETE FROM lessons_ai_tasks WHERE lesson_id = _lesson_id;
  END IF;
END;
$function$;

-- 3. Strip the dead key from stored lesson snapshots (history stays readable;
--    the live prompt is in each snapshot's `ai_task`).
UPDATE lms.content_versions
   SET snapshot = snapshot - 'ai_task_instructions'
 WHERE content_type = 'lesson' AND snapshot ? 'ai_task_instructions';

-- 4. Drop the column (no views/other objects depend on it).
ALTER TABLE lms.lessons DROP COLUMN IF EXISTS ai_task_instructions;

-- ===========================================================================
-- 20261023120000_exam_image_course_trailer.sql
-- ===========================================================================
-- Exams get a cover image (like lessons.image); courses get a trailer / intro
-- video shown on the public course page.
ALTER TABLE lms.exams ADD COLUMN IF NOT EXISTS image text;
ALTER TABLE lms.courses ADD COLUMN IF NOT EXISTS trailer_url text;

-- ===========================================================================
-- 20261024120000_ai_evals_lesson_task.sql
-- ===========================================================================
-- AI evals F1 (lesson AI task): prompt versions, eval cases (goldens +
-- scenarios), runs and results, plus the version stamp on real student chats.
-- Design: docs/plans/AI_EVALS_AND_SCENARIOS.md.
--
-- Every table carries tenant_id and is staff-only (is_staff_of): snapshots and
-- cases hold the teacher's private prompt, which students must never read.
-- Versions are written only by the SECURITY DEFINER helper below (the save
-- trigger and the eval routes through the service role); run status and
-- results are written only by the runner (service role).

-- 1. Prompt versions -------------------------------------------------------

CREATE TABLE lms.ai_config_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES lms.tenants(id) ON DELETE CASCADE,
  target_type text NOT NULL CHECK (target_type IN ('lesson_ai_task')),
  target_id bigint NOT NULL,
  version_no integer NOT NULL,
  config_hash text NOT NULL,
  snapshot jsonb NOT NULL,
  created_by uuid DEFAULT auth.uid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (target_type, target_id, config_hash),
  UNIQUE (target_type, target_id, version_no)
);

CREATE INDEX ai_config_versions_tenant_idx ON lms.ai_config_versions (tenant_id);

COMMENT ON TABLE lms.ai_config_versions IS
  'Immutable snapshots of an AI task config (prompt, task, requirements). One row per distinct config; the live lessons_ai_tasks row maps to the version with the same hash.';

-- The canonical snapshot. jsonb::text is key-ordered, so md5 of it is stable.
CREATE OR REPLACE FUNCTION lms.lesson_task_config_snapshot(
  _task_instructions text, _system_prompt text, _requirements jsonb
)
RETURNS jsonb
LANGUAGE sql IMMUTABLE
AS $$
  SELECT jsonb_build_object(
    'task_instructions', coalesce(_task_instructions, ''),
    'system_prompt', coalesce(_system_prompt, ''),
    'requirements', _requirements
  );
$$;

-- Returns the version for a config, creating it (next version_no) when new.
-- Not exposed to clients: callers verify the lesson's tenant first.
CREATE OR REPLACE FUNCTION lms.ensure_lesson_task_version(
  _lesson_id bigint, _task_instructions text, _system_prompt text, _requirements jsonb
)
RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'lms', 'public'
AS $$
DECLARE
  _tenant uuid;
  _snapshot jsonb := lms.lesson_task_config_snapshot(_task_instructions, _system_prompt, _requirements);
  _hash text := md5(_snapshot::text);
  _id uuid;
BEGIN
  SELECT tenant_id INTO _tenant FROM lessons WHERE id = _lesson_id;
  IF _tenant IS NULL THEN
    RAISE EXCEPTION 'lesson % not found', _lesson_id;
  END IF;

  SELECT id INTO _id FROM ai_config_versions
   WHERE target_type = 'lesson_ai_task' AND target_id = _lesson_id AND config_hash = _hash;
  IF _id IS NOT NULL THEN
    RETURN _id;
  END IF;

  -- Serialise version_no allocation per lesson.
  PERFORM pg_advisory_xact_lock(hashtext('ai_config_versions:lesson_ai_task:' || _lesson_id));

  INSERT INTO ai_config_versions (tenant_id, target_type, target_id, version_no, config_hash, snapshot)
  SELECT _tenant, 'lesson_ai_task', _lesson_id,
         coalesce(max(version_no), 0) + 1, _hash, _snapshot
    FROM ai_config_versions
   WHERE target_type = 'lesson_ai_task' AND target_id = _lesson_id
  ON CONFLICT (target_type, target_id, config_hash) DO NOTHING
  RETURNING id INTO _id;

  IF _id IS NULL THEN
    SELECT id INTO _id FROM ai_config_versions
     WHERE target_type = 'lesson_ai_task' AND target_id = _lesson_id AND config_hash = _hash;
  END IF;
  RETURN _id;
END;
$$;

REVOKE EXECUTE ON FUNCTION lms.ensure_lesson_task_version(bigint, text, text, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.ensure_lesson_task_version(bigint, text, text, jsonb) TO service_role;

-- Every save of the live task (server action RPC, MCP, restore) records a version.
CREATE OR REPLACE FUNCTION lms.trg_lessons_ai_tasks_version()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'lms', 'public'
AS $$
BEGIN
  IF NEW.lesson_id IS NOT NULL THEN
    PERFORM lms.ensure_lesson_task_version(NEW.lesson_id, NEW.task_instructions, NEW.system_prompt, NEW.requirements);
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER lessons_ai_tasks_version
  AFTER INSERT OR UPDATE OF task_instructions, system_prompt, requirements ON lms.lessons_ai_tasks
  FOR EACH ROW EXECUTE FUNCTION lms.trg_lessons_ai_tasks_version();

-- Backfill: the current config of every existing task becomes its v1.
SELECT lms.ensure_lesson_task_version(t.lesson_id, t.task_instructions, t.system_prompt, t.requirements)
  FROM lms.lessons_ai_tasks t
  JOIN lms.lessons l ON l.id = t.lesson_id;

-- 2. Real chats carry the version students were served ---------------------

ALTER TABLE lms.lessons_ai_task_messages
  ADD COLUMN IF NOT EXISTS config_version_id uuid REFERENCES lms.ai_config_versions(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS lessons_ai_task_messages_version_idx
  ON lms.lessons_ai_task_messages (lesson_id, config_version_id);

-- Stamped in the database so no write path can forget it.
CREATE OR REPLACE FUNCTION lms.trg_lessons_ai_task_messages_version()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'lms', 'public'
AS $$
BEGIN
  IF NEW.config_version_id IS NULL AND NEW.lesson_id IS NOT NULL THEN
    SELECT v.id INTO NEW.config_version_id
      FROM lessons_ai_tasks t
      JOIN ai_config_versions v
        ON v.target_type = 'lesson_ai_task'
       AND v.target_id = t.lesson_id
       AND v.config_hash = md5(lms.lesson_task_config_snapshot(t.task_instructions, t.system_prompt, t.requirements)::text)
     WHERE t.lesson_id = NEW.lesson_id;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER lessons_ai_task_messages_version
  BEFORE INSERT ON lms.lessons_ai_task_messages
  FOR EACH ROW EXECUTE FUNCTION lms.trg_lessons_ai_task_messages_version();

-- 3. Suites, cases, runs, results ------------------------------------------

CREATE TABLE lms.ai_eval_suites (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES lms.tenants(id) ON DELETE CASCADE,
  target_type text NOT NULL CHECK (target_type IN ('lesson_ai_task')),
  target_id bigint NOT NULL,
  -- Regenerate untouched generated scenarios when the config changes.
  auto_regenerate boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (target_type, target_id)
);

CREATE TABLE lms.ai_eval_cases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES lms.tenants(id) ON DELETE CASCADE,
  target_type text NOT NULL CHECK (target_type IN ('lesson_ai_task')),
  target_id bigint NOT NULL,
  kind text NOT NULL CHECK (kind IN ('golden_chat', 'scenario')),
  source text NOT NULL CHECK (source IN ('preview', 'real_chat', 'generated', 'teacher')),
  name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 200),
  importance_note text CHECK (char_length(importance_note) <= 2000),
  -- { "completed": true | false | null }  (null = either is fine)
  expected jsonb NOT NULL DEFAULT '{}'::jsonb,
  -- Plain-language criteria the judge checks ("does not reveal the answer").
  must_keep text[] NOT NULL DEFAULT '{}',
  -- golden_chat: { "messages": [{ "role": "user"|"assistant", "text": "..." }] }
  -- scenario:    { "persona", "goal", "script": [...], "max_turns" }
  input jsonb NOT NULL,
  -- golden_chat: what happened when it was saved ({ completed, completed_turn, version_id })
  golden_output jsonb,
  generated_for_version_id uuid REFERENCES lms.ai_config_versions(id) ON DELETE SET NULL,
  teacher_edited boolean NOT NULL DEFAULT false,
  created_by uuid DEFAULT auth.uid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX ai_eval_cases_target_idx ON lms.ai_eval_cases (target_type, target_id);
CREATE INDEX ai_eval_cases_tenant_idx ON lms.ai_eval_cases (tenant_id);

CREATE TABLE lms.ai_eval_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES lms.tenants(id) ON DELETE CASCADE,
  target_type text NOT NULL CHECK (target_type IN ('lesson_ai_task')),
  target_id bigint NOT NULL,
  version_id uuid NOT NULL REFERENCES lms.ai_config_versions(id) ON DELETE CASCADE,
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'done', 'failed')),
  -- { total, passed, drifted, verdict_changes, avg_deviation, model_calls }
  summary jsonb,
  -- { tutor, verifier, simulator, judge } as "provider/model"
  model_ids jsonb,
  error text,
  created_by uuid DEFAULT auth.uid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  started_at timestamptz,
  finished_at timestamptz
);

CREATE INDEX ai_eval_runs_target_idx ON lms.ai_eval_runs (target_type, target_id, created_at DESC);
CREATE INDEX ai_eval_runs_tenant_idx ON lms.ai_eval_runs (tenant_id);
-- One active run per target: a second "Run" while one is going is refused.
CREATE UNIQUE INDEX ai_eval_runs_one_active_idx
  ON lms.ai_eval_runs (target_type, target_id) WHERE status IN ('queued', 'running');

CREATE TABLE lms.ai_eval_results (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES lms.tenants(id) ON DELETE CASCADE,
  run_id uuid NOT NULL REFERENCES lms.ai_eval_runs(id) ON DELETE CASCADE,
  -- Kept when the case is deleted later, so old reports still read.
  case_id uuid REFERENCES lms.ai_eval_cases(id) ON DELETE SET NULL,
  case_name text NOT NULL,
  case_kind text NOT NULL,
  -- The case's expected outcome at run time ({ "completed": true|false|null }).
  expected jsonb NOT NULL DEFAULT '{}'::jsonb,
  -- [{ "role": "user"|"assistant", "text": "..." }]
  transcript jsonb NOT NULL DEFAULT '[]'::jsonb,
  completed boolean,
  completed_turn integer,
  -- [{ "criterion", "passed", "evidence" }]
  verdicts jsonb NOT NULL DEFAULT '[]'::jsonb,
  deviation integer CHECK (deviation BETWEEN 0 AND 100),
  passed boolean,
  error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (run_id, case_id)
);

CREATE INDEX ai_eval_results_run_idx ON lms.ai_eval_results (run_id);
CREATE INDEX ai_eval_results_tenant_idx ON lms.ai_eval_results (tenant_id);

-- 4. RLS --------------------------------------------------------------------

ALTER TABLE lms.ai_config_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE lms.ai_eval_suites ENABLE ROW LEVEL SECURITY;
ALTER TABLE lms.ai_eval_cases ENABLE ROW LEVEL SECURITY;
ALTER TABLE lms.ai_eval_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE lms.ai_eval_results ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON lms.ai_config_versions, lms.ai_eval_suites, lms.ai_eval_cases,
  lms.ai_eval_runs, lms.ai_eval_results FROM anon;

CREATE POLICY ai_config_versions_staff_select ON lms.ai_config_versions
  FOR SELECT TO authenticated USING ((SELECT lms.is_staff_of(tenant_id)));

CREATE POLICY ai_eval_suites_staff_all ON lms.ai_eval_suites
  FOR ALL TO authenticated
  USING ((SELECT lms.is_staff_of(tenant_id)))
  WITH CHECK ((SELECT lms.is_staff_of(tenant_id)));

CREATE POLICY ai_eval_cases_staff_all ON lms.ai_eval_cases
  FOR ALL TO authenticated
  USING ((SELECT lms.is_staff_of(tenant_id)))
  WITH CHECK ((SELECT lms.is_staff_of(tenant_id)));

CREATE POLICY ai_eval_runs_staff_select ON lms.ai_eval_runs
  FOR SELECT TO authenticated USING ((SELECT lms.is_staff_of(tenant_id)));

CREATE POLICY ai_eval_runs_staff_insert ON lms.ai_eval_runs
  FOR INSERT TO authenticated
  WITH CHECK ((SELECT lms.is_staff_of(tenant_id)) AND created_by = (SELECT auth.uid()) AND status = 'queued');

CREATE POLICY ai_eval_results_staff_select ON lms.ai_eval_results
  FOR SELECT TO authenticated USING ((SELECT lms.is_staff_of(tenant_id)));

-- 5. Real-usage metrics per version ------------------------------------------
-- SECURITY INVOKER: RLS on lessons_ai_task_messages and ai_config_versions
-- decides what the caller sees (staff of the lesson's tenant).

CREATE OR REPLACE FUNCTION lms.lesson_task_version_metrics(_lesson_id bigint)
RETURNS TABLE (
  version_id uuid,
  version_no integer,
  created_at timestamptz,
  students integer,
  completed integer,
  median_turns_to_complete numeric,
  abandoned integer
)
LANGUAGE sql STABLE SECURITY INVOKER
SET search_path TO 'lms', 'public'
AS $$
  WITH msgs AS (
    SELECT m.user_id, m.config_version_id AS v, m.sender, m.created_at, m.tool_invocations
      FROM lessons_ai_task_messages m
     WHERE m.lesson_id = _lesson_id AND m.config_version_id IS NOT NULL
  ),
  done AS (
    SELECT user_id, v, min(created_at) AS done_at
      FROM msgs
     WHERE sender = 'assistant'
       AND jsonb_typeof(tool_invocations) = 'array'
       AND EXISTS (
         SELECT 1 FROM jsonb_array_elements(tool_invocations) e
          WHERE e->>'toolName' = 'markLessonCompleted' AND e->'output'->>'success' = 'true'
       )
     GROUP BY user_id, v
  ),
  per AS (
    SELECT m.user_id, m.v, d.done_at,
           count(*) FILTER (WHERE m.sender = 'user' AND (d.done_at IS NULL OR m.created_at <= d.done_at)) AS turns,
           max(m.created_at) AS last_at
      FROM msgs m
      LEFT JOIN done d ON d.user_id = m.user_id AND d.v = m.v
     GROUP BY m.user_id, m.v, d.done_at
  )
  SELECT ver.id, ver.version_no, ver.created_at,
         count(per.user_id)::integer,
         count(per.done_at)::integer,
         (percentile_cont(0.5) WITHIN GROUP (ORDER BY per.turns) FILTER (WHERE per.done_at IS NOT NULL))::numeric,
         (count(*) FILTER (WHERE per.user_id IS NOT NULL AND per.done_at IS NULL AND per.last_at < now() - interval '48 hours'))::integer
    FROM ai_config_versions ver
    LEFT JOIN per ON per.v = ver.id
   WHERE ver.target_type = 'lesson_ai_task' AND ver.target_id = _lesson_id
   GROUP BY ver.id, ver.version_no, ver.created_at
   ORDER BY ver.version_no DESC;
$$;

REVOKE EXECUTE ON FUNCTION lms.lesson_task_version_metrics(bigint) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION lms.lesson_task_version_metrics(bigint) TO authenticated;

