-- Advisor follow-ups for 20261024120000_ai_evals_lesson_task:
-- pin the snapshot helper's search_path, and keep the SECURITY DEFINER trigger
-- functions out of the client API (triggers fire without EXECUTE).

ALTER FUNCTION lms.lesson_task_config_snapshot(text, text, jsonb) SET search_path TO '';

REVOKE EXECUTE ON FUNCTION lms.trg_lessons_ai_tasks_version() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION lms.trg_lessons_ai_task_messages_version() FROM PUBLIC, anon, authenticated;

-- ===========================================================================
-- 20261025120000_ai_evals_exercise_grader.sql
-- ===========================================================================
-- AI evals F2 (graded exercises): the eval tables learn a second target,
-- `exercise` (AI-graded written/artifact exercises), a `graded_answer` case
-- kind and score columns on results. Design: docs/plans/AI_EVALS_AND_SCENARIOS.md.
--
-- RLS is unchanged: the F1 policies are staff-only and target-agnostic.

-- 1. Targets and case kind ---------------------------------------------------

ALTER TABLE lms.ai_config_versions DROP CONSTRAINT IF EXISTS ai_config_versions_target_type_check;
ALTER TABLE lms.ai_config_versions
  ADD CONSTRAINT ai_config_versions_target_type_check CHECK (target_type IN ('lesson_ai_task', 'exercise'));

ALTER TABLE lms.ai_eval_suites DROP CONSTRAINT IF EXISTS ai_eval_suites_target_type_check;
ALTER TABLE lms.ai_eval_suites
  ADD CONSTRAINT ai_eval_suites_target_type_check CHECK (target_type IN ('lesson_ai_task', 'exercise'));

ALTER TABLE lms.ai_eval_cases DROP CONSTRAINT IF EXISTS ai_eval_cases_target_type_check;
ALTER TABLE lms.ai_eval_cases
  ADD CONSTRAINT ai_eval_cases_target_type_check CHECK (target_type IN ('lesson_ai_task', 'exercise'));

ALTER TABLE lms.ai_eval_runs DROP CONSTRAINT IF EXISTS ai_eval_runs_target_type_check;
ALTER TABLE lms.ai_eval_runs
  ADD CONSTRAINT ai_eval_runs_target_type_check CHECK (target_type IN ('lesson_ai_task', 'exercise'));

ALTER TABLE lms.ai_eval_cases DROP CONSTRAINT IF EXISTS ai_eval_cases_kind_check;
ALTER TABLE lms.ai_eval_cases
  ADD CONSTRAINT ai_eval_cases_kind_check CHECK (kind IN ('golden_chat', 'scenario', 'graded_answer'));

-- 2. Graded results ----------------------------------------------------------
-- One row per case: the grader runs each answer several times and the repeats
-- are folded into these columns (UNIQUE (run_id, case_id) still holds).

ALTER TABLE lms.ai_eval_results
  ADD COLUMN IF NOT EXISTS scores integer[],
  ADD COLUMN IF NOT EXISTS score numeric,
  ADD COLUMN IF NOT EXISTS score_stddev numeric,
  ADD COLUMN IF NOT EXISTS output jsonb;

COMMENT ON COLUMN lms.ai_eval_results.scores IS 'graded_answer: one score per repeat.';
COMMENT ON COLUMN lms.ai_eval_results.score IS 'graded_answer: median of scores.';
COMMENT ON COLUMN lms.ai_eval_results.score_stddev IS 'graded_answer: population stddev of scores.';
COMMENT ON COLUMN lms.ai_eval_results.output IS 'graded_answer: the median repeat''s { feedback, strengths, improvements, passed }.';

-- 3. Exercise grader versions ------------------------------------------------

-- Everything the grader sees, with the staff-only grading secrets merged back
-- (secrets.config over exercise_config, secrets.system_prompt over the column).
CREATE OR REPLACE FUNCTION lms.exercise_grader_config_snapshot(_exercise_id bigint)
RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO ''
AS $$
  SELECT jsonb_build_object(
    'title', e.title,
    'instructions', coalesce(e.instructions, ''),
    'exercise_type', e.exercise_type::text,
    'system_prompt', coalesce(nullif(s.system_prompt, ''), e.system_prompt, ''),
    'exercise_config', coalesce(e.exercise_config, '{}'::jsonb) || coalesce(s.config, '{}'::jsonb)
  )
    FROM lms.exercises e
    LEFT JOIN lms.exercise_grading_secrets s ON s.exercise_id = e.id
   WHERE e.id = _exercise_id;
$$;

-- Returns the version for the exercise's current grader config, creating it
-- (next version_no) when new. Service role only: callers verify the tenant.
CREATE OR REPLACE FUNCTION lms.ensure_exercise_grader_version(_exercise_id bigint)
RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  _tenant uuid;
  _snapshot jsonb;
  _hash text;
  _id uuid;
BEGIN
  SELECT tenant_id INTO _tenant FROM lms.exercises WHERE id = _exercise_id;
  IF _tenant IS NULL THEN
    RAISE EXCEPTION 'exercise % not found', _exercise_id;
  END IF;

  _snapshot := lms.exercise_grader_config_snapshot(_exercise_id);
  _hash := md5(_snapshot::text);

  SELECT id INTO _id FROM lms.ai_config_versions
   WHERE target_type = 'exercise' AND target_id = _exercise_id AND config_hash = _hash;
  IF _id IS NOT NULL THEN
    RETURN _id;
  END IF;

  -- Serialise version_no allocation per exercise.
  PERFORM pg_advisory_xact_lock(hashtext('ai_config_versions:exercise:' || _exercise_id));

  INSERT INTO lms.ai_config_versions (tenant_id, target_type, target_id, version_no, config_hash, snapshot)
  SELECT _tenant, 'exercise', _exercise_id,
         coalesce(max(version_no), 0) + 1, _hash, _snapshot
    FROM lms.ai_config_versions
   WHERE target_type = 'exercise' AND target_id = _exercise_id
  ON CONFLICT (target_type, target_id, config_hash) DO NOTHING
  RETURNING id INTO _id;

  IF _id IS NULL THEN
    SELECT id INTO _id FROM lms.ai_config_versions
     WHERE target_type = 'exercise' AND target_id = _exercise_id AND config_hash = _hash;
  END IF;
  RETURN _id;
END;
$$;

REVOKE EXECUTE ON FUNCTION lms.exercise_grader_config_snapshot(bigint) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.exercise_grader_config_snapshot(bigint) TO service_role;
REVOKE EXECUTE ON FUNCTION lms.ensure_exercise_grader_version(bigint) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.ensure_exercise_grader_version(bigint) TO service_role;

-- ===========================================================================
-- 20261025130000_ai_eval_runs_insert_guard.sql
-- ===========================================================================
-- AI evals hardening: a staff member of tenant A must not be able to queue a run
-- for a lesson/exercise of tenant B (the one-active-run index would then block
-- B's own runs). Two changes:
--   1. the one-active-run index is per tenant, and
--   2. the run INSERT policy also requires the target to belong to tenant_id and
--      version_id to be a version of that very target in that tenant.

-- 1. Index ---------------------------------------------------------------------

DROP INDEX IF EXISTS lms.ai_eval_runs_one_active_idx;
CREATE UNIQUE INDEX ai_eval_runs_one_active_idx
  ON lms.ai_eval_runs (tenant_id, target_type, target_id) WHERE status IN ('queued', 'running');

-- 2. Insert guard --------------------------------------------------------------
-- SECURITY DEFINER so the check does not depend on the caller's read access to
-- lessons / exercises / versions; it only answers yes or no.

CREATE OR REPLACE FUNCTION lms.ai_eval_run_target_ok(
  _tenant_id uuid, _target_type text, _target_id bigint, _version_id uuid
)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO ''
AS $$
  -- Answers only for the caller's own staff tenant, so a direct RPC call can't
  -- probe which ids belong to another school.
  SELECT lms.is_staff_of(_tenant_id)
     AND CASE _target_type
           WHEN 'lesson_ai_task' THEN EXISTS (
             SELECT 1 FROM lms.lessons l WHERE l.id = _target_id AND l.tenant_id = _tenant_id)
           WHEN 'exercise' THEN EXISTS (
             SELECT 1 FROM lms.exercises e WHERE e.id = _target_id AND e.tenant_id = _tenant_id)
           ELSE false
         END
     AND EXISTS (
       SELECT 1 FROM lms.ai_config_versions v
        WHERE v.id = _version_id
          AND v.tenant_id = _tenant_id
          AND v.target_type = _target_type
          AND v.target_id = _target_id);
$$;

REVOKE EXECUTE ON FUNCTION lms.ai_eval_run_target_ok(uuid, text, bigint, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION lms.ai_eval_run_target_ok(uuid, text, bigint, uuid) TO authenticated, service_role;

DROP POLICY IF EXISTS ai_eval_runs_staff_insert ON lms.ai_eval_runs;
CREATE POLICY ai_eval_runs_staff_insert ON lms.ai_eval_runs
  FOR INSERT TO authenticated
  WITH CHECK (
    (SELECT lms.is_staff_of(tenant_id))
    AND created_by = (SELECT auth.uid())
    AND status = 'queued'
    AND (SELECT lms.ai_eval_run_target_ok(tenant_id, target_type, target_id, version_id))
  );

